def read_claude_billing_policy(
    path: Path | None = None, *, today: dt.date | None = None
) -> dict[str, Any]:
    """Read only the routing fields needed from the owner billing declaration."""
    configured_path = os.environ.get("AGENT_FLEET_BILLING_MODE_PATH")
    source = (
        path
        if path is not None
        else Path(configured_path).expanduser()
        if configured_path
        else DEFAULT_BILLING_MODE_PATH
    )
    neutral = {
        "status": "missing",
        "mode": None,
        "valid_until": None,
        "last_resort_agents": [],
    }
    try:
        document = json.loads(source.read_text(encoding="utf-8"))
    except FileNotFoundError:
        return neutral
    except (OSError, json.JSONDecodeError):
        return {
            "status": "invalid",
            "mode": None,
            "valid_until": None,
            "last_resort_agents": ["claude"],
        }
    if not isinstance(document, dict):
        return {
            "status": "invalid",
            "mode": None,
            "valid_until": None,
            "last_resort_agents": ["claude"],
        }
    entry = document.get("claude")
    if entry is None:
        tools = document.get("narzedzia")
        entry = tools.get("claude") if isinstance(tools, dict) else None
    if entry is None:
        return neutral
    if not isinstance(entry, dict):
        return {
            "status": "invalid",
            "mode": None,
            "valid_until": None,
            "last_resort_agents": ["claude"],
        }
    mode = entry.get("tryb")
    if mode not in {"normalny", "oszczedny", "kredytowy"}:
        return {
            "status": "invalid",
            "mode": None,
            "valid_until": None,
            "last_resort_agents": ["claude"],
        }
    valid_until_value = entry.get("wazne_do")
    try:
        valid_from = (
            dt.date.fromisoformat(str(entry["od"]))
            if entry.get("od") is not None
            else None
        )
        valid_until = (
            dt.date.fromisoformat(str(valid_until_value))
            if valid_until_value is not None
            else None
        )
    except (TypeError, ValueError):
        return {
            "status": "invalid",
            "mode": mode,
            "valid_until": None,
            "last_resort_agents": ["claude"],
        }
    if mode != "kredytowy":
        return {
            "status": "neutral",
            "mode": mode,
            "valid_until": valid_until.isoformat() if valid_until else None,
            "last_resort_agents": [],
        }
    if valid_until is None:
        return {
            "status": "invalid",
            "mode": mode,
            "valid_until": None,
            "last_resort_agents": ["claude"],
        }
    current_date = today or dt.date.today()
    if valid_from is not None and current_date < valid_from:
        return {
            "status": "scheduled",
            "mode": mode,
            "valid_until": valid_until.isoformat(),
            "last_resort_agents": [],
        }
    if current_date <= valid_until:
        return {
            "status": "active-credit",
            "mode": mode,
            "valid_until": valid_until.isoformat(),
            "last_resort_agents": ["claude"],
        }
    return {
        "status": "expired",
        "mode": mode,
        "valid_until": valid_until.isoformat(),
        "last_resort_agents": [],
    }


def apply_billing_last_resort_order(
    rows: list[dict[str, Any]], policy: dict[str, Any]
) -> list[dict[str, Any]]:
    last_resort_agents = {
        str(agent) for agent in policy.get("last_resort_agents", [])
    }
    for row in rows:
        is_last_resort = str(row.get("agent")) in last_resort_agents
        row["billing_last_resort"] = is_last_resort
        if is_last_resort and "billing-credit-last-resort" not in row["reasons"]:
            row["reasons"].append("billing-credit-last-resort")

    def partition(ordered: list[dict[str, Any]]) -> list[dict[str, Any]]:
        return sorted(
            ordered,
            key=lambda row: (
                not bool(row.get("eligible")),
                bool(row.get("billing_last_resort")),
            ),
        )

    baseline_order = partition(
        sorted(rows, key=lambda row: int(row.get("baseline_rank", 10**9)))
    )
    for index, row in enumerate(baseline_order, start=1):
        row["baseline_rank"] = index
    selected_order = partition(rows)
    for index, row in enumerate(selected_order, start=1):
        row["adaptive_rank"] = index
    return selected_order


def utc_now() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat().replace("+00:00", "Z")


def canonical_json_bytes(value: Any) -> bytes:
    return (
        json.dumps(value, ensure_ascii=True, sort_keys=True, indent=2) + "\n"
    ).encode("ascii")


def sha256_text(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def sha256_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


REQUIRED_INPUTS_SCHEMA_VERSION = 1
REQUIRED_INPUT_MAX_FILES = 256
REQUIRED_INPUT_SECRET_SEGMENTS = {
    ".env",
    "credentials",
    "secrets",
    "private",
    "private-key",
}
REQUIRED_INPUT_SECRET_SUFFIXES = {".pem", ".key", ".p12", ".pfx", ".kdbx"}


def load_required_inputs_manifest(path: str | Path) -> tuple[Path, list[dict[str, str]]]:
    manifest_candidate = Path(path).expanduser()
    if is_filesystem_link(manifest_candidate):
        raise FleetError(f"Required-inputs manifest is linked: {manifest_candidate}")
    manifest_path = manifest_candidate.resolve(strict=False)
    if not manifest_path.is_file() or is_filesystem_link(manifest_path):
        raise FleetError(f"Required-inputs manifest is missing or linked: {manifest_path}")
    try:
        value = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise FleetError(f"Required-inputs manifest is not valid JSON: {manifest_path}") from exc
    if isinstance(value, dict):
        if value.get("schema_version", REQUIRED_INPUTS_SCHEMA_VERSION) != REQUIRED_INPUTS_SCHEMA_VERSION:
            raise FleetError("Required-inputs manifest schema_version is unsupported")
        entries = value.get("inputs")
    else:
        entries = value
    if (
        not isinstance(entries, list)
        or not entries
        or len(entries) > REQUIRED_INPUT_MAX_FILES
    ):
        raise FleetError(
            f"Required-inputs manifest must contain 1..{REQUIRED_INPUT_MAX_FILES} inputs"
        )
    normalized: list[dict[str, str]] = []
    for index, entry in enumerate(entries):
        if not isinstance(entry, dict):
            raise FleetError(f"Required-inputs entry {index} is not an object")
        relative_value = entry.get("path")
        digest = entry.get("sha256")
        if not isinstance(relative_value, str) or not relative_value.strip():
            raise FleetError(f"Required-inputs entry {index} has no relative path")
        if ":" in relative_value or relative_value.startswith(("/", "\\")):
            raise FleetError(
                f"Required-inputs entry {index} uses unsafe Windows path syntax"
            )
        relative = Path(relative_value)
        if (
            relative.is_absolute()
            or not relative.parts
            or any(part in {"", ".", ".."} for part in relative.parts)
        ):
            raise FleetError(f"Required-inputs entry {index} must stay relative")
        lowered_parts = {part.casefold() for part in relative.parts}
        if (
            lowered_parts & REQUIRED_INPUT_SECRET_SEGMENTS
            or relative.name.casefold().startswith(".env")
            or relative.suffix.casefold() in REQUIRED_INPUT_SECRET_SUFFIXES
        ):
            raise FleetError(f"Required-inputs entry {index} names a secret-bearing file")
        if not isinstance(digest, str) or re.fullmatch(r"[0-9a-fA-F]{64}", digest) is None:
            raise FleetError(f"Required-inputs entry {index} has an invalid sha256")
        normalized.append(
            {"path": relative.as_posix(), "sha256": digest.casefold()}
        )
    if len({entry["path"] for entry in normalized}) != len(normalized):
        raise FleetError("Required-inputs manifest contains duplicate paths")
    return manifest_path, normalized


def preflight_required_inputs(
    execution_workspace: Path, entries: list[dict[str, str]]
) -> list[dict[str, Any]]:
    root = execution_workspace.expanduser().resolve(strict=False)
    if not root.is_dir() or is_filesystem_link(root):
        raise FleetError(f"Required-inputs workspace is missing or linked: {root}")
    verified: list[dict[str, Any]] = []
    for entry in entries:
        relative = Path(entry["path"])
        current = root
        for component in relative.parts:
            current = current / component
            if is_filesystem_link(current):
                raise FleetError(f"Required input is linked: {entry['path']}")
        try:
            candidate = current.resolve(strict=False)
            candidate_is_file = candidate.is_file()
            candidate_is_link = is_filesystem_link(candidate)
        except (OSError, ValueError) as exc:
            raise FleetError(
                f"Required input is missing from execution worktree: {entry['path']}"
            ) from exc
        try:
            candidate.relative_to(root)
        except ValueError as exc:
            raise FleetError(f"Required input escapes execution worktree: {entry['path']}") from exc
        if not candidate_is_file or candidate_is_link:
            raise FleetError(
                f"Required input is missing from execution worktree: {entry['path']}"
            )
        content = candidate.read_bytes()
        findings = scan_sensitive_source(content, entry["path"])
        if findings:
            raise FleetError(
                f"Required input appears to contain secret material: {entry['path']}: "
                + ", ".join(sorted(set(findings)))
            )
        digest = sha256_bytes(content)
        if digest != entry["sha256"]:
            raise FleetError(
                f"Required input hash mismatch: {entry['path']} "
                f"expected={entry['sha256']} actual={digest}"
            )
        verified.append(
            {"path": entry["path"], "sha256": digest, "size_bytes": len(content)}
        )
    return verified


def codex_l2_config_args() -> list[str]:
    args: list[str] = []
    for override in CODEX_L2_CONFIG_OVERRIDES:
        args.extend(["-c", override])
    for feature in CODEX_L2_DISABLED_FEATURES:
        args.extend(["--disable", feature])
    return args


def validate_l2_adapter_configuration(
    adapter_id: str, executable: str, workspace: Path
) -> dict[str, Any]:
    if adapter_id != "codex":
        return {"status": "NOT_REQUIRED", "adapter": adapter_id}
    command = [
        executable,
        "debug",
        "prompt-input",
        *codex_l2_config_args(),
        "L2 adapter configuration validation only",
    ]
    try:
        with tempfile.TemporaryDirectory(prefix="agent-fleet-codex-l2-") as temporary:
            root = Path(temporary)
            home = root / "debug-home"
            home.mkdir()
            env = sanitized_environment(inherit_api_keys=False, native_subagent_limit=0)
            env["CODEX_HOME"] = str(home)
            completed = subprocess.run(
                command,
                cwd=str(workspace),
                env=env,
                stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=60,
                check=False,
            )
            if completed.returncode != 0:
                detail = (completed.stderr or completed.stdout).strip()[:2000]
                raise FleetError(f"Codex L2 configuration preflight failed: {detail}")
            prompt_input_bytes = len(completed.stdout.encode("utf-8"))
            if "<INSTRUCTIONS>" in completed.stdout:
                raise FleetError(
                    "Codex L2 configuration preflight found ambient instructions"
                )
            if prompt_input_bytes > MAX_CODEX_L2_PROMPT_INPUT_BYTES:
                raise FleetError(
                    "Codex L2 configuration preflight exceeded the context limit: "
                    f"{prompt_input_bytes}>{MAX_CODEX_L2_PROMPT_INPUT_BYTES} bytes"
                )
            windows_write_probe = (
                validate_codex_windows_workspace_write(executable, root)
                if os.name == "nt"
                else {"status": "NOT_REQUIRED", "platform": os.name}
            )
    except subprocess.TimeoutExpired as exc:
        raise FleetError("Codex L2 configuration preflight timed out") from exc
    return {
        "status": "PASS",
        "adapter": adapter_id,
        "exit_code": completed.returncode,
        "prompt_input_bytes": prompt_input_bytes,
        "max_prompt_input_bytes": MAX_CODEX_L2_PROMPT_INPUT_BYTES,
        "ambient_instructions_present": False,
        "isolated_codex_home": True,
        "windows_workspace_write_probe": windows_write_probe,
        "config_fingerprint": sha256_bytes(
            canonical_json_bytes(codex_l2_config_args())
        ),
    }


def validate_codex_windows_workspace_write(
    executable: str, root: Path
) -> dict[str, Any]:
    run_dir = root / "sandbox-run"
    workspace = root / "sandbox-workspace"
    run_dir.mkdir()
    workspace.mkdir()
    probe_token = "AGENT_FLEET_WRITE_PROBE_OK"
    env = sanitized_environment(inherit_api_keys=False, native_subagent_limit=0)
    env["CODEX_HOME"] = str(prepare_guarded_codex_home(run_dir))
    command = [
        executable,
        "sandbox",
        "-P",
        ":workspace",
        "-C",
        str(workspace),
        *codex_l2_config_args(),
        "--",
        "powershell.exe",
        "-NoProfile",
        "-NonInteractive",
        "-Command",
        "$path = Join-Path (Get-Location) '.agent-fleet-write-probe'; "
        "[IO.File]::WriteAllText($path, 'ok'); "
        "$value = [IO.File]::ReadAllText($path); "
        "[IO.File]::Delete($path); "
        "if ($value -ne 'ok' -or [IO.File]::Exists($path)) { exit 17 }; "
        f"[Console]::Out.Write('{probe_token}')",
    ]
    try:
        completed = subprocess.run(
            command,
            cwd=str(workspace),
            env=env,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=30,
            check=False,
        )
        if completed.returncode != 0 or completed.stdout.strip() != probe_token:
            detail = (completed.stderr or completed.stdout).strip()[:2000]
            raise FleetError(
                "Codex Windows workspace-write preflight failed: "
                f"exit={completed.returncode}; {detail}"
            )
        return {
            "status": "PASS",
            "platform": "windows",
            "exit_code": completed.returncode,
            "sandbox": "elevated",
            "permission_profile": ":workspace",
        }
    except subprocess.TimeoutExpired as exc:
        raise FleetError("Codex Windows workspace-write preflight timed out") from exc
    finally:
        remove_guarded_codex_home(run_dir)


def load_json(path: Path, label: str) -> Any:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise FleetError(f"Cannot load {label}: {path}: {exc}") from exc


def toml_key(value: str) -> str:
    if re.fullmatch(r"[A-Za-z0-9_-]+", value):
        return value
    return json.dumps(value, ensure_ascii=True)


def toml_value(value: Any) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, str):
        return json.dumps(value, ensure_ascii=True)
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return str(value)
    if isinstance(value, list):
        return "[" + ", ".join(toml_value(item) for item in value) + "]"
    raise FleetError(
        f"Unsupported value in guarded Kimi config: {type(value).__name__}"
    )


def emit_toml_table(
    lines: list[str], path: tuple[str, ...], mapping: dict[str, Any]
) -> None:
    scalars = {
        key: value for key, value in mapping.items() if not isinstance(value, dict)
    }
    nested = {key: value for key, value in mapping.items() if isinstance(value, dict)}
    if path and scalars:
        lines.append("[" + ".".join(toml_key(item) for item in path) + "]")
    for key, value in scalars.items():
        lines.append(f"{toml_key(key)} = {toml_value(value)}")
    if path and scalars:
        lines.append("")
    for key, value in nested.items():
        emit_toml_table(lines, (*path, key), value)


def clean_kimi_section(
    section: dict[str, Any], allowed: set[str], *, label: str
) -> dict[str, Any]:
    api_key = section.get("api_key")
    env_values = section.get("env")
    if api_key not in (None, "") or (
        isinstance(env_values, dict) and any(value for value in env_values.values())
    ):
        raise FleetError(
            f"Guarded Kimi adapter refuses plaintext credentials in {label}; use managed OAuth"
        )
    return {key: section[key] for key in allowed if key in section}


def build_guarded_kimi_config(
    source_config: Path,
    *,
    model: str,
    mode: str,
    native_subagent_limit: int,
    enable_web: bool,
    chrome_assignment: dict[str, Any] | None = None,
) -> str:
    try:
        with source_config.open("rb") as handle:
            source = tomllib.load(handle)
    except (OSError, tomllib.TOMLDecodeError) as exc:
        raise FleetError(
            f"Cannot read Kimi config safely: {source_config}: {exc}"
        ) from exc

    models = source.get("models")
    if not isinstance(models, dict) or not isinstance(models.get(model), dict):
        raise FleetError(f"Kimi model is not configured locally: {model}")
    model_source = models[model]
    provider_id = model_source.get("provider")
    providers = source.get("providers")
    if (
        not isinstance(provider_id, str)
        or not isinstance(providers, dict)
        or not isinstance(providers.get(provider_id), dict)
    ):
        raise FleetError(f"Kimi provider for model {model} is not configured")
    provider = clean_kimi_section(
        providers[provider_id],
        {"type", "base_url", "oauth"},
        label=f"provider {provider_id}",
    )
    if not isinstance(provider.get("oauth"), dict):
        raise FleetError("Guarded Kimi adapter requires a managed OAuth provider")

    model_config = clean_kimi_section(
        model_source,
        {
            "provider",
            "model",
            "max_context_size",
            "max_output_size",
            "capabilities",
            "support_efforts",
            "default_effort",
            "display_name",
            "reasoning_key",
            "adaptive_thinking",
            "overrides",
        },
        label=f"model {model}",
    )
    # Kimi CLI 0.43.1 retries while attempt < max_attempts_per_step (attempts
    # start at 1), so 5 attempts give the intended 4 retries. The deprecated
    # max_retries_per_step key is ignored by the CLI and must not be emitted.
    # max_steps_per_turn depends on the mode: a flat cap of 64 killed an
    # implement run on 2026-09-24 after 27.7 min of real work
    # ("loop.max_steps_exceeded: Turn exceeded maxSteps=64"), so implement gets
    # a wide budget while read-only advisory/review runs stay tighter - they
    # produce a single analysis without edit/verify cycles. The task timeout,
    # not the step cap, remains the real runaway safeguard.
    max_steps_per_turn = 512 if mode == "implement" else 128
    guarded: dict[str, Any] = {
        "default_model": model,
        "default_permission_mode": "manual",
        "default_plan_mode": False,
        "merge_all_available_skills": True,
        "telemetry": False,
        "providers": {provider_id: provider},
        "models": {model: model_config},
        "loop_control": {
            "max_attempts_per_step": 5,
            "max_steps_per_turn": max_steps_per_turn,
        },
        "background": {
            "keep_alive_on_exit": False,
            "bash_auto_background_on_timeout": False,
            "bash_task_timeout_s": 300,
            "print_background_mode": "exit",
            "print_wait_ceiling_s": 300,
            "print_max_turns": 64,
        },
        "subagent": {"timeout_ms": 600000},
    }
    if enable_web:
        source_services = source.get("services")
        services: dict[str, Any] = {}
        if isinstance(source_services, dict):
            for service_id in ("moonshot_search", "moonshot_fetch"):
                service = source_services.get(service_id)
                if isinstance(service, dict):
                    services[service_id] = clean_kimi_section(
                        service,
                        {"base_url", "oauth"},
                        label=f"service {service_id}",
                    )
        if services:
            guarded["services"] = services

    lines: list[str] = []
    emit_toml_table(lines, (), guarded)
    denied_tools = [
        "AskUserQuestion",
        "CronCreate",
        "CronDelete",
        "TaskStop",
    ]
    if mode != "implement":
        denied_tools[:0] = ["Write", "Edit", "Bash"]
    if native_subagent_limit <= 0:
        denied_tools.extend(["Agent", "AgentSwarm"])
    if not enable_web:
        denied_tools.extend(["WebSearch", "FetchURL"])
    chrome_tools: tuple[str, ...] = ()
    if chrome_assignment is not None:
        try:
            import fleet_chrome_integration as chrome
            chrome.validate_fleet_assignment(chrome_assignment, "kimi")
            if chrome_assignment["mode"] != mode:
                raise ValueError("mode mismatch")
            chrome_tools = chrome.mcp_tool_names(chrome_assignment)
        except (ImportError, ValueError) as exc:
            raise FleetError("Guarded Kimi Chrome assignment is invalid") from exc
        for name in chrome_tools:
            pattern = toml_value("mcp__fleet-chrome-relay__" + name)
            lines.extend(["[[permission.rules]]", 'decision = "allow"',
                          f"pattern = {pattern}",
                          'reason = "Agent Fleet exact managed Chrome assignment"', ""])
    for tool_name in denied_tools:
        lines.extend(
            [
                "[[permission.rules]]",
                'decision = "deny"',
                f"pattern = {toml_value(tool_name)}",
                'reason = "Agent Fleet contractor boundary"',
                "",
            ]
        )
    return "\n".join(lines).rstrip() + "\n"


def prepare_guarded_kimi_home(
    run_dir: Path,
    *,
    model: str,
    mode: str,
    native_subagent_limit: int,
    enable_web: bool,
    chrome_assignment: dict[str, Any] | None = None,
) -> Path:
    source_home = kimi_usage.account_home()
    home = run_dir / "kimi-home"
    home.mkdir(parents=True, exist_ok=False)
    config = build_guarded_kimi_config(
        source_home / "config.toml",
        model=model,
        mode=mode,
        native_subagent_limit=native_subagent_limit,
        enable_web=enable_web,
        chrome_assignment=chrome_assignment,
    )
    (home / "config.toml").write_text(config, encoding="utf-8", newline="\n")
    if chrome_assignment is not None:
        import fleet_chrome_integration as chrome
        chrome.validate_fleet_assignment(chrome_assignment, "kimi")
        (home / "mcp.json").write_text(
            json.dumps(chrome.kimi_mcp_config(chrome_assignment), separators=(",", ":")) + "\n",
            encoding="utf-8", newline="\n")
    source_credentials = source_home / "credentials"
    if not source_credentials.is_dir():
        raise FleetError(
            f"Kimi managed OAuth credential store is missing: {source_credentials}"
        )
    create_directory_link(source_credentials.resolve(), home / "credentials")
    return home


def prepare_contractor_skills(
    run_dir: Path, *, materialize: bool, source_root: Path | None = None
) -> Path:
    target = run_dir / "approved-skills"
    if not materialize:
        return target
    source = source_root or (Path.home() / ".agents" / "skills")
    target.mkdir(parents=True, exist_ok=False)
    if not source.is_dir():
        return target
    for skill in sorted(source.iterdir(), key=lambda item: item.name.casefold()):
        if (
            is_filesystem_link(skill)
            or not skill.is_dir()
            or skill.name.casefold() in BLOCKED_CONTRACTOR_SKILLS
        ):
            continue
        copy_tree_without_links(skill, target / skill.name)
    return target


def prepare_shared_knowledge_snapshot(
    run_dir: Path,
    *,
    materialize: bool,
    config_path: Path | None = None,
) -> Path | None:
    config = config_path or (Path.home() / ".agents" / "knowledge-config.json")
    if not config.is_file():
        return None
    try:
        raw = json.loads(config.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError):
        return None
    if not isinstance(raw, dict) or not str(raw.get("vault_path", "")).strip():
        return None
    vault = Path(str(raw["vault_path"])).expanduser().resolve()
    wiki = vault / "wiki"
    if not wiki.is_dir():
        return None
    target = run_dir / "knowledge-snapshot"
    if not materialize:
        return target
    target.mkdir(parents=True, exist_ok=False)
    copy_tree_without_links(wiki, target / "wiki")
    vault_rules = vault / "AGENTS.md"
    if vault_rules.is_file():
        if is_filesystem_link(vault_rules):
            raise FleetError(f"Refusing linked shared-knowledge file: {vault_rules}")
        shutil.copy2(vault_rules, target / "AGENTS.md")
    return target


def is_filesystem_link(path: Path) -> bool:
    try:
        attributes = int(getattr(path.lstat(), "st_file_attributes", 0))
    except OSError:
        attributes = 0
    reparse_point = int(getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400))
    if attributes & reparse_point:
        return True
    is_junction = getattr(path, "is_junction", None)
    return path.is_symlink() or bool(is_junction and is_junction())


def load_optional_incidents() -> Any | None:
    """Load only the sibling collector agreed with the incident-index owner."""
    path = Path(__file__).resolve().with_name("incidents.py")
    if not path.is_file() or is_filesystem_link(path):
        return None
    module_name = "_agent_fleet_optional_incidents"
    cached = sys.modules.get(module_name)
    if cached is not None:
        return cached
    spec = importlib.util.spec_from_file_location(module_name, path)
    if spec is None or spec.loader is None:
        return None
    module = importlib.util.module_from_spec(spec)
    sys.modules[module_name] = module
    try:
        spec.loader.exec_module(module)
    except Exception:
        sys.modules.pop(module_name, None)
        raise
    if not callable(getattr(module, "record_event", None)) or not callable(
        getattr(module, "report", None)
    ):
        raise RuntimeError("incident-api-mismatch")
    sys.modules[module_name] = module
    return module


def _incident_warning(code: str) -> dict[str, Any]:
    return {"status": "WARNING", "warning_code": code}


def record_incident_event(root: Path, event: dict[str, Any]) -> dict[str, Any]:
    """Fail open; never echo collector exceptions or event content."""
    try:
        module = load_optional_incidents()
        if module is None:
            return _incident_warning(INCIDENT_LOGGER_UNAVAILABLE)
        result = module.record_event(root, event)
        if not isinstance(result, dict):
            raise RuntimeError("incident-result-invalid")
        return result
    except Exception:
        return _incident_warning(INCIDENT_LOGGER_FAILED)


def incident_report(root: Path) -> dict[str, Any]:
    try:
        module = load_optional_incidents()
        if module is None:
            warning = _incident_warning(INCIDENT_LOGGER_UNAVAILABLE)
            return {"action": "incident-report", **warning, "status": "UNAVAILABLE"}
        result = module.report(root)
        if not isinstance(result, dict):
            raise RuntimeError("incident-report-invalid")
        return result
    except Exception:
        warning = _incident_warning(INCIDENT_LOGGER_FAILED)
        return {"action": "incident-report", **warning, "status": "UNAVAILABLE"}


def incident_semantics(code: str, outcome: str) -> dict[str, Any]:
    normalized = {
        'completed': 'success', 'failed': 'failure', 'partial': 'blocked',
        'rejected': 'blocked', 'repair': 'blocked', 'investigate': 'observed',
        'recorded': 'observed', 'refused': 'blocked',
    }.get(outcome.casefold(), outcome.casefold())
    classification = 'unknown'
    if code in {'timeout', 'run-timeout', 'auditor-transport'}:
        classification = 'harness_transport'
    elif code == 'quota-blocked':
        classification = 'resource'
    elif code == 'missing-input-or-binding':
        classification = 'spec_input'
    elif normalized in {'success', 'accepted', 'observed'}:
        classification = 'not_failure'
    result = {'error_code': code, 'outcome': normalized, 'classification': classification}
    if code == 'possible-regression':
        result['issue_status'] = 'regression_possible'
    return result


def run_incident_event(
    record: dict[str, Any], *, stage: str, code: str, outcome: str
) -> dict[str, Any]:
    runtime = record.get("runtime_attestation")
    runtime = runtime if isinstance(runtime, dict) else {}
    usage = record.get("token_usage")
    usage = usage if isinstance(usage, dict) else {}
    known_usage = usage.get("status") == "known"
    return {
        "schema_version": 1,
        "source": "fleet",
        "stage": stage,
        **incident_semantics(code, outcome),
        "occurred_at": (
            utc_now()
            if stage == "acceptance"
            else record.get("completed_at") or utc_now()
        ),
        "run_id": record.get("run_id"),
        "root_task_id": record.get("root_task_id"),
        "attempt_id": record.get("attempt_id"),
        "profile": record.get("agent"),
        "model": record.get("model"),
        "provider": record.get("model_provider_id"),
        "runtime_hash": runtime.get("payload_fingerprint"),
        "release_hash": runtime.get("package_fingerprint"),
        "duration_ms": (
            record['duration_seconds'] * 1000
            if type(record.get('duration_seconds')) in (int, float)
            and 0 <= record['duration_seconds'] <= 86400 else None
        ),
        "retry_count": record.get("continuation_count"),
        "recovery_outcome": "unknown",
        "input_tokens": usage.get("input_tokens") if known_usage else None,
        "output_tokens": usage.get("output_tokens") if known_usage else None,
        "total_tokens": usage.get("total_tokens") if known_usage else None,
    }


def gate_incident_event(
    *,
    gate_id: str,
    group_id: str,
    gate_kind: str,
    code: str,
    outcome: str,
    attempt_index: int,
    auditor: dict[str, Any] | None = None,
) -> dict[str, Any]:
    auditor = auditor if isinstance(auditor, dict) else {}
    return {
        "schema_version": 1,
        "source": "fleet",
        "stage": "auditor" if code == "auditor-transport" else "quality-gate",
        **incident_semantics(code, outcome),
        "occurred_at": utc_now(),
        "gate_id": gate_id,
        "group_id": group_id,
        "event_type": gate_kind,
        "attempt_index": attempt_index,
        "profile": auditor.get("agent"),
        "model": auditor.get("model"),
        "provider": auditor.get("model_provider_id"),
    }


def refused_incident_event(action: str | None, error: Exception) -> dict[str, Any]:
    text = str(error).casefold()
    code = (
        "quota-blocked"
        if "quota" in text
        else "timeout"
        if "timeout" in text or "timed out" in text
        else "missing-input-or-binding"
        if any(marker in text for marker in ("missing", "does not exist", "binding"))
        else "cli-refused"
    )
    return {
        "schema_version": 1,
        "source": "fleet",
        "stage": str(action or "cli"),
        **incident_semantics(code, "refused"),
        "occurred_at": utc_now(),
    }


def windows_extended_io_path(path: Path) -> Path:
    """Return an extended-length Windows path without changing its identity."""
    if os.name != "nt":
        return path
    absolute = path if path.is_absolute() else path.absolute()
    text = str(absolute)
    if text.startswith("\\\\?\\"):
        return absolute
    if text.startswith("\\\\"):
        return Path("\\\\?\\UNC\\" + text[2:])
    return Path("\\\\?\\" + text)


def copy_tree_without_links(source: Path, target: Path) -> None:
    if is_filesystem_link(source):
        raise FleetError(f"Refusing linked contractor input tree: {source}")
    target.mkdir(parents=True, exist_ok=False)
    for item in sorted(
        source.iterdir(), key=lambda candidate: candidate.name.casefold()
    ):
        if is_filesystem_link(item):
            raise FleetError(f"Refusing linked contractor input: {item}")
        destination = target / item.name
        if item.is_dir():
            copy_tree_without_links(item, destination)
        elif item.is_file():
            shutil.copy2(item, destination)


def is_directory_link(path: Path) -> bool:
    return is_filesystem_link(path)


def prepare_guarded_codex_home(run_dir: Path) -> Path:
    source_home = Path(
        os.environ.get("CODEX_HOME", str(Path.home() / ".codex"))
    ).expanduser()
    source_auth = source_home / "auth.json"
    if not source_auth.is_file() or is_filesystem_link(source_auth):
        raise FleetError(
            f"Codex managed authentication file is missing or linked: {source_auth}"
        )
    source_sandbox = source_home / ".sandbox"
    source_sandbox_bin = source_home / ".sandbox-bin"
    source_sandbox_secrets = source_home / ".sandbox-secrets"
    source_marker = source_sandbox / "setup_marker.json"
    source_cap_sid = source_home / "cap_sid"
    if (
        not source_sandbox.is_dir()
        or is_filesystem_link(source_sandbox)
        or not source_sandbox_bin.is_dir()
        or is_filesystem_link(source_sandbox_bin)
        or not source_sandbox_secrets.is_dir()
        or is_filesystem_link(source_sandbox_secrets)
        or not source_marker.is_file()
        or is_filesystem_link(source_marker)
        or not source_cap_sid.is_file()
        or is_filesystem_link(source_cap_sid)
    ):
        raise FleetError(
            "Codex managed Windows sandbox state is missing or linked in an "
            f"unexpected way: {source_home}"
        )
    home = run_dir / "codex-home"
    home.mkdir(parents=True, exist_ok=False)
    target_auth = home / "auth.json"
    try:
        os.link(source_auth, target_auth)
        if not os.path.samefile(source_auth, target_auth):
            raise FleetError("Codex authentication hardlink verification failed")
        target_sandbox = home / ".sandbox"
        target_sandbox.mkdir()
        for name in CODEX_L2_SANDBOX_COPY_FILES:
            source_file = source_sandbox / name
            if not source_file.exists():
                continue
            if not source_file.is_file() or is_filesystem_link(source_file):
                raise FleetError(
                    f"Refusing unsafe Codex sandbox state file: {source_file}"
                )
            shutil.copy2(source_file, target_sandbox / name)
        create_directory_link(source_sandbox_bin, home / ".sandbox-bin")
        create_directory_link(source_sandbox_secrets, home / ".sandbox-secrets")
        for name in CODEX_L2_SANDBOX_HARDLINK_FILES:
            source_file = source_home / name
            if not source_file.exists():
                continue
            if not source_file.is_file() or is_filesystem_link(source_file):
                raise FleetError(
                    f"Refusing unsafe Codex sandbox metadata file: {source_file}"
                )
            target_file = home / name
            os.link(source_file, target_file)
            if not os.path.samefile(source_file, target_file):
                raise FleetError(
                    f"Codex sandbox metadata hardlink verification failed: {name}"
                )
    except (OSError, FleetError) as exc:
        try:
            remove_guarded_directory_link(home / ".sandbox-bin", "Codex sandbox")
            remove_guarded_directory_link(
                home / ".sandbox-secrets", "Codex sandbox secrets"
            )
        except (OSError, FleetError):
            pass
        shutil.rmtree(home, ignore_errors=True)
        raise FleetError(
            "Cannot create the guarded Codex home required for isolated L2 execution"
        ) from exc
    return home


def remove_guarded_codex_home(run_dir: Path) -> None:
    home = run_dir / "codex-home"
    if not home.exists():
        return
    if is_filesystem_link(home) or home.parent.resolve() != run_dir.resolve():
        raise FleetError(f"Refusing unsafe Codex home cleanup: {home}")
    remove_guarded_directory_link(home / ".sandbox-bin", "Codex sandbox")
    remove_guarded_directory_link(home / ".sandbox-secrets", "Codex sandbox secrets")
    shutil.rmtree(home)
    if home.exists():
        raise FleetError(f"Codex home cleanup did not complete: {home}")


def create_directory_link(source: Path, link: Path) -> None:
    try:
        os.symlink(source, link, target_is_directory=True)
        return
    except OSError as symlink_error:
        if os.name != "nt":
            raise FleetError(
                "Cannot create the guarded temporary directory link"
            ) from symlink_error
    completed = subprocess.run(
        ["cmd.exe", "/d", "/c", "mklink", "/J", str(link), str(source)],
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        encoding="utf-8",
        errors="replace",
        timeout=10,
        check=False,
    )
    if completed.returncode != 0 or not is_directory_link(link):
        raise FleetError("Cannot create the guarded temporary directory junction")


def remove_guarded_directory_link(link: Path, label: str) -> None:
    if is_directory_link(link):
        if link.is_symlink():
            link.unlink()
        else:
            os.rmdir(link)
    elif link.exists():
        raise FleetError(f"Refusing to remove unexpected non-link {label}: {link}")


def remove_guarded_kimi_credential_link(run_dir: Path) -> None:
    link = run_dir / "kimi-home" / "credentials"
    remove_guarded_directory_link(link, "Kimi credential path")


def local_runtime_backend(raw: dict[str, Any]) -> Any:
    if not isinstance(raw, dict):
        raise FleetError("Local Qwen runtime must be an object")
    kind = str(raw.get("kind", ""))
    if kind == openclaw_runtime.OPENCLAW_LOCAL_RUNTIME_KIND:
        return openclaw_runtime
    if kind == "vllm-wsl":
        return qwen_local_runtime
    if kind == "ollama-windows-external":
        return ollama_local_runtime
    raise FleetError(f"Unsupported local Qwen runtime kind: {kind or '<missing>'}")


def validate_local_runtime(
    raw: dict[str, Any], *, require_executable: bool = True
) -> dict[str, Any]:
    backend = local_runtime_backend(raw)
    try:
        if backend is ollama_local_runtime:
            return backend.validate_config(raw, require_executable=require_executable)
        return backend.validate_config(raw)
    except (qwen_local_runtime.LocalRuntimeError, ollama_local_runtime.LocalRuntimeError, openclaw_runtime.OpenClawRuntimeError) as exc:
        raise FleetError(str(exc)) from exc


