def prepare_guarded_opencode_environment(run_dir: Path) -> dict[str, str]:
    home = run_dir / "opencode-home"
    if home.exists() or is_filesystem_link(home):
        raise FleetError(f"Guarded OpenCode home already exists or is linked: {home}")
    home.mkdir(parents=True)
    paths = {
        "config": home / "config",
        "data": home / "data",
        "cache": home / "cache",
        "state": home / "state",
    }
    for path in paths.values():
        path.mkdir()
    return {
        "XDG_CONFIG_HOME": str(paths["config"]),
        "XDG_DATA_HOME": str(paths["data"]),
        "XDG_CACHE_HOME": str(paths["cache"]),
        "XDG_STATE_HOME": str(paths["state"]),
        "OPENCODE_CONFIG_DIR": str(paths["config"]),
        "OPENCODE_DISABLE_PROJECT_CONFIG": "true",
        "OPENCODE_DISABLE_CLAUDE_CODE": "true",
        "OPENCODE_DISABLE_DEFAULT_PLUGINS": "true",
        "OPENCODE_DISABLE_LSP_DOWNLOAD": "true",
        "OPENCODE_DISABLE_MODELS_FETCH": "true",
        "OPENCODE_ENABLE_EXA": "false",
    }


def remove_guarded_opencode_home(run_dir: Path) -> None:
    home = run_dir / "opencode-home"
    if not home.exists():
        return
    if is_filesystem_link(home) or home.parent.resolve() != run_dir.resolve():
        raise FleetError(f"Refusing unsafe OpenCode home cleanup: {home}")
    cleanup_path: str | Path = home
    if os.name == "nt":
        resolved = str(home.resolve())
        if resolved.startswith("\\\\"):
            cleanup_path = "\\\\?\\UNC\\" + resolved.lstrip("\\")
        else:
            cleanup_path = "\\\\?\\" + resolved
    last_error: OSError | None = None

    def ignore_disappearing_child(
        _function: Callable[..., Any],
        _path: str,
        exc_info: tuple[type[BaseException], BaseException, Any],
    ) -> None:
        error = exc_info[1]
        if isinstance(error, FileNotFoundError):
            return
        raise error

    for attempt in range(4):
        if not home.exists():
            return
        try:
            shutil.rmtree(cleanup_path, onerror=ignore_disappearing_child)
        except (FileNotFoundError, PermissionError) as exc:
            last_error = exc
        if not home.exists():
            return
        if attempt < 3:
            time.sleep(0.05 * (attempt + 1))
    if last_error is not None:
        raise FleetError(
            f"OpenCode home cleanup did not complete after bounded retries: {home}: {last_error}"
        ) from last_error
    raise FleetError(f"OpenCode home cleanup did not complete: {home}")


def validate_opencode_resolved_config(
    executable: str,
    workspace: Path,
    env: dict[str, str],
    expected_read_admissions: tuple[str, ...] = (),
    expected_office_mcp: dict[str, Any] | None = None,
    profile: dict[str, Any] | None = None,
    mode: str = "review",
) -> dict[str, Any]:
    if is_mercury_profile(profile):
        qualify_mercury_workspace(profile, workspace)
        mercury_runtime_module().require_native(executable)
        if expected_read_admissions or expected_office_mcp is not None:
            raise FleetError("Mercury resolved config cannot mount external admissions or Office")
    try:
        completed = subprocess.run(
            [executable, "--pure", "debug", "config"],
            cwd=str(workspace),
            env=env,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=60,
            check=False,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        raise FleetError(
            f"OpenCode resolved-config preflight failed: {type(exc).__name__}"
        ) from exc
    if completed.returncode != 0:
        raise FleetError(
            "OpenCode resolved-config preflight failed with exit code "
            f"{completed.returncode}"
        )
    try:
        config = json.loads(completed.stdout)
    except json.JSONDecodeError as exc:
        raise FleetError(
            "OpenCode resolved-config preflight returned invalid JSON"
        ) from exc
    if not isinstance(config, dict):
        raise FleetError("OpenCode resolved-config preflight returned a non-object")
    permission = config.get("permission")
    if not isinstance(permission, dict):
        raise FleetError("OpenCode resolved permissions are missing")
    beam_write_allowed = (is_beam_profile(profile) or is_mercury_profile(profile)) and mode == "implement"
    denied = {
        "bash",
        "task",
        "skill",
        "webfetch",
        "websearch",
        "external_directory",
        "question",
        "doom_loop",
        "todowrite",
        "lsp",
    }
    failed_permissions = sorted(key for key in denied if permission.get(key) != "deny")
    expected_edit = beam_edit_permission() if beam_write_allowed else "deny"
    if permission.get("edit") != expected_edit:
        failed_permissions.append("edit")
    read_permission = permission.get("read")
    resolved_mcp = config.get("mcp")
    if expected_office_mcp is None:
        unsafe_mcp = bool(resolved_mcp)
        office_permission_leak = any(
            str(key).startswith(f"{OFFICE_MCP_SERVER_NAME}_") for key in permission
        )
    else:
        # Exactly one server, the contractor Office with the exact argv, and
        # allow rules for exactly its tools - nothing ambient merged in.
        expected_entry = opencode_office_mcp_entry(expected_office_mcp)
        unsafe_mcp = not (
            isinstance(resolved_mcp, dict)
            and set(resolved_mcp) == {OFFICE_MCP_SERVER_NAME}
            and isinstance(resolved_mcp[OFFICE_MCP_SERVER_NAME], dict)
            # Exactly these keys: an extra `environment`, `timeout` or `url` could
            # repoint the Office identity/home or the transport.
            and set(resolved_mcp[OFFICE_MCP_SERVER_NAME]) == {"type", "command", "enabled"}
            and resolved_mcp[OFFICE_MCP_SERVER_NAME].get("type") == "local"
            and resolved_mcp[OFFICE_MCP_SERVER_NAME].get("command") == expected_entry["command"]
            and resolved_mcp[OFFICE_MCP_SERVER_NAME].get("enabled") is True
        )
        office_rules = {
            key: value for key, value in permission.items()
            if str(key).startswith(f"{OFFICE_MCP_SERVER_NAME}_")
        }
        office_permission_leak = office_rules != opencode_office_tool_permissions()
    unsafe_extensions = unsafe_mcp or office_permission_leak or bool(config.get("plugin"))
    unsafe_instructions = bool(config.get("instructions"))
    provider_contract = opencode_profile_provider_contract(
        profile if profile is not None else default_opencode_profile()
    )
    provider_config = config.get("provider")
    selected_provider = (
        provider_config.get(provider_contract["provider_id"])
        if isinstance(provider_config, dict)
        else None
    )
    resolved_models = (
        selected_provider.get("models")
        if isinstance(selected_provider, dict)
        else None
    )
    expected_model_ids = set(provider_contract["models"])
    resolved_whitelist = (
        selected_provider.get("whitelist")
        if isinstance(selected_provider, dict)
        else None
    )
    missing_admissions = [
        pattern
        for pattern in expected_read_admissions
        if not isinstance(read_permission, dict) or read_permission.get(pattern) != "allow"
    ]
    secret_directory_allows = []
    if isinstance(read_permission, dict):
        expected_allow = {"*", *expected_read_admissions}
        for key, value in read_permission.items():
            if value != "allow" or key in expected_allow:
                continue
            lowered = str(key).replace("\\", "/").casefold()
            if "secrets" in lowered.split("/") or lowered.endswith("**/secrets/**"):
                secret_directory_allows.append(key)
    if (
        permission.get("*") != "deny"
        or not isinstance(read_permission, dict)
        or read_permission.get("*") != "allow"
        or read_permission.get("**/secrets/**") != "deny"
        or read_permission.get("**/credentials/**") != "deny"
        or failed_permissions
        or unsafe_extensions
        or unsafe_instructions
        or missing_admissions
        or secret_directory_allows
        or (is_beam_profile(profile) and expected_office_mcp is not None)
        or config.get("enabled_providers") != provider_contract["enabled_providers"]
        or set(resolved_models or {}) != expected_model_ids
        or (
            "whitelist" in provider_contract["provider"][provider_contract["provider_id"]]
            and set(resolved_whitelist or []) != expected_model_ids
        )
        or config.get("share") != "disabled"
        or config.get("autoupdate") is not False
        or config.get("lsp") is not False
        or config.get("formatter") is not False
    ):
        raise FleetError(
            "OpenCode resolved-config preflight rejected merged instructions, "
            "extensions, providers, or permissions"
        )
    if is_mercury_profile(profile):
        # Compare full effective provider, permissions and agents, not just IDs.
        safe = redact_sensitive_value(config, exact_secret=env.get("INCEPTION_API_KEY"))
        expected = json.loads(opencode_runtime_config(profile=profile, mode=mode))
        expected["provider"]["inception"]["options"]["apiKey"] = "[REDACTED]"
        # debug config may leave the env placeholder unresolved.
        if safe.get("provider", {}).get("inception", {}).get("options", {}).get("apiKey") == "{env:INCEPTION_API_KEY}":
            safe["provider"]["inception"]["options"]["apiKey"] = "[REDACTED]"
        # Native 1.18.21 expands omitted agent fields into empty objects.
        # Only these inert defaults are equivalent; populated overrides still fail.
        for document in (safe, expected):
            for agent in document.get("agent", {}).values():
                if isinstance(agent, dict):
                    for field in ("options", "permission"):
                        if agent.get(field) == {}:
                            agent.pop(field)
        if any(safe.get(key) != expected[key] for key in expected):
            raise FleetError("Mercury resolved config drift")
    return {
        "status": "PASS",
        "adapter": "opencode",
        "project_config_disabled": True,
        "claude_compatibility_disabled": True,
        "mcp_count": 0 if expected_office_mcp is None else 1,
        "mcp_servers": [] if expected_office_mcp is None else [OFFICE_MCP_SERVER_NAME],
        "plugin_count": 0,
        "instruction_count": 0,
        "denied_permissions": sorted(denied),
        "provider_allowlist": provider_contract["enabled_providers"],
        "model_allowlist": sorted(expected_model_ids),
    }


OPENCODE_MCP_CONNECTED_RE = re.compile(r"\b" + re.escape(OFFICE_MCP_SERVER_NAME) + r"\s+connected\b")
OPENCODE_MCP_COUNT_RE = re.compile(r"\b(\d+)\s+server\(s\)")
ANSI_ESCAPE_RE = re.compile(r"\x1b\[[0-9;]*m")


def opencode_office_mcp_connection(executable: str, workspace: Path, env: dict[str, str]) -> dict[str, Any]:
    """Runtime proof before the model starts: `opencode mcp list` in the run env.

    The CLI actually starts and connects every configured server; the probe
    passes only when it reports exactly one server and `office connected`.
    """
    try:
        completed = subprocess.run(
            [executable, "--pure", "mcp", "list"], cwd=str(workspace), env=env,
            stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            text=True, encoding="utf-8", errors="replace", timeout=90, check=False,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        return {"status": "unavailable", "error": type(exc).__name__}
    text = ANSI_ESCAPE_RE.sub("", completed.stdout or "")
    count = OPENCODE_MCP_COUNT_RE.search(text)
    connected = bool(OPENCODE_MCP_CONNECTED_RE.search(text))
    ok = completed.returncode == 0 and connected and count is not None and int(count.group(1)) == 1
    return {
        "status": "connected" if ok else "not-connected",
        "servers_reported": int(count.group(1)) if count else None,
        "exit_code": completed.returncode,
    }


def codex_office_mcp_table(office_mcp: dict[str, Any]) -> str:
    """TOML inline table for `-c mcp_servers.office=...` (JSON strings are TOML-safe).

    Approval is scoped to this per-run server only: approval_policy stays
    "never" for everything else, and enabled_tools pins the contractor tools.
    """
    tools = sorted(OFFICE_MCP_TOOLS)
    return (
        "{command=" + json.dumps(str(office_mcp["command"]))
        + ",args=[" + ",".join(json.dumps(str(a)) for a in office_mcp["args"]) + "]"
        + ',default_tools_approval_mode="approve"'
        + ",enabled_tools=[" + ",".join(json.dumps(t) for t in tools) + "]}"
    )


def codex_mcp_isolation_args(
    ambient_servers: Iterable[str], office_mcp: dict[str, Any] | None,
    chrome_assignment: dict[str, Any] | None = None,
) -> list[str]:
    """Disable apps/plugins and every ambient MCP server; optionally mount office.

    `-c mcp_servers={}` does not remove servers of the user config (the override
    merges), so each ambient server is switched off by name.
    """
    args: list[str] = []
    for feature in CODEX_AMBIENT_DISABLED_FEATURES:
        args.extend(["--disable", feature])
    for name in sorted(set(ambient_servers)):
        if CODEX_MCP_SERVER_NAME_PATTERN.fullmatch(name) is None:
            raise FleetError(f"Codex ambient MCP server name cannot be disabled safely: {name!r}")
        if name == CODEX_OFFICE_MCP_SERVER_NAME and office_mcp is not None:
            raise FleetError(
                f"Codex ambient MCP server collides with the per-run name {CODEX_OFFICE_MCP_SERVER_NAME!r}"
            )
        if name == CHROME_MCP_SERVER_NAME and chrome_assignment is not None:
            raise FleetError("Codex ambient MCP server collides with the assigned Chrome relay")
        args.extend(["-c", f"mcp_servers.{name}.enabled=false"])
    if office_mcp is not None:
        args.extend(["-c", f"mcp_servers.{CODEX_OFFICE_MCP_SERVER_NAME}=" + codex_office_mcp_table(office_mcp)])
    if chrome_assignment is not None:
        import fleet_chrome_integration
        args.extend(["-c", f"mcp_servers.{CHROME_MCP_SERVER_NAME}=" +
                     fleet_chrome_integration.codex_inline_table(chrome_assignment)])
    return args


def codex_office_mcp_effective(
    executable: str, workspace: Path, env: dict[str, str], extra_args: list[str],
    office_mcp: dict[str, Any],
) -> dict[str, Any]:
    """`codex mcp get <name> --json` with the run overrides must equal the table.

    Exactly stdio + command + args, no env/env_vars/cwd, enabled_tools = the
    contractor tools and no disabled_tools; anything merged in is a mismatch.
    """
    try:
        completed = subprocess.run(
            [executable, "mcp", "get", CODEX_OFFICE_MCP_SERVER_NAME, "--json", *extra_args],
            cwd=str(workspace), env=env, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
            stderr=subprocess.PIPE, text=True, encoding="utf-8", errors="replace", timeout=60, check=False,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        return {"status": "unavailable", "error": type(exc).__name__}
    if completed.returncode != 0:
        return {"status": "unavailable", "error": f"exit-{completed.returncode}"}
    try:
        row = json.loads(completed.stdout)
    except json.JSONDecodeError:
        return {"status": "unavailable", "error": "invalid-json"}
    if not isinstance(row, dict):
        return {"status": "unavailable", "error": "invalid-json"}
    transport = row.get("transport") if isinstance(row.get("transport"), dict) else {}
    problems: list[str] = []
    if row.get("enabled") is not True:
        problems.append("not-enabled")
    if set(transport) - {"type", "command", "args", "env", "env_vars", "cwd"}:
        problems.append("unexpected-transport-fields")
    if transport.get("type") != "stdio":
        problems.append("transport-type")
    if transport.get("command") != str(office_mcp["command"]):
        problems.append("command")
    if transport.get("args") != [str(a) for a in office_mcp["args"]]:
        problems.append("args")
    if transport.get("env") not in (None, {}):
        problems.append("env")
    if transport.get("env_vars") not in (None, []):
        problems.append("env_vars")
    if transport.get("cwd") is not None:
        problems.append("cwd")
    if row.get("enabled_tools") != sorted(OFFICE_MCP_TOOLS):
        problems.append("enabled_tools")
    if row.get("disabled_tools") not in (None, []):
        problems.append("disabled_tools")
    return {"status": "exact" if not problems else "mismatch", "problems": problems}


def codex_chrome_mcp_effective(executable: str, workspace: Path, env: dict[str, str],
                               extra_args: list[str], assignment: dict[str, Any]) -> dict[str, Any]:
    try:
        completed = subprocess.run(
            [executable, "mcp", "get", CHROME_MCP_SERVER_NAME, "--json", *extra_args],
            cwd=str(workspace), env=env, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
            stderr=subprocess.PIPE, text=True, encoding="utf-8", errors="replace", timeout=60, check=False)
        if completed.returncode != 0:
            return {"status": "unavailable", "error": f"exit-{completed.returncode}"}
        row = json.loads(completed.stdout)
        import fleet_chrome_integration
        expected = fleet_chrome_integration.mcp_entry(assignment)
    except (OSError, subprocess.TimeoutExpired, json.JSONDecodeError, ImportError, ValueError, TypeError):
        return {"status": "unavailable", "error": "probe-or-assignment"}
    if not isinstance(row, dict):
        return {"status": "unavailable", "error": "invalid-json"}
    transport = row.get("transport") if isinstance(row.get("transport"), dict) else {}
    problems = []
    if row.get("enabled") is not True: problems.append("not-enabled")
    if set(transport) - {"type", "command", "args", "env", "env_vars", "cwd"}: problems.append("transport-fields")
    if transport.get("type") != "stdio": problems.append("transport-type")
    if transport.get("command") != expected["command"]: problems.append("command")
    if transport.get("args") != expected["args"]: problems.append("args")
    if transport.get("env") not in (None, {}): problems.append("env")
    if transport.get("env_vars") not in (None, []): problems.append("env-vars")
    if transport.get("cwd") is not None: problems.append("cwd")
    # `enabled_tools` contains server-local tool IDs. The prefixed names are
    # conversation routing IDs, not the native MCP configuration filter.
    allowed = sorted(fleet_chrome_integration.mcp_tool_names(assignment))
    if row.get("enabled_tools") != allowed: problems.append("enabled-tools")
    if row.get("disabled_tools") not in (None, []): problems.append("disabled-tools")
    return {"status": "exact" if not problems else "mismatch", "problems": problems}


def codex_mcp_servers(
    executable: str, workspace: Path, env: dict[str, str], extra_args: list[str]
) -> dict[str, Any]:
    """`codex mcp list --json` with the run's overrides: every server and its state."""
    try:
        completed = subprocess.run(
            [executable, "mcp", "list", "--json", *extra_args], cwd=str(workspace), env=env,
            stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            text=True, encoding="utf-8", errors="replace", timeout=60, check=False,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        return {"status": "unavailable", "error": type(exc).__name__}
    if completed.returncode != 0:
        return {"status": "unavailable", "error": f"exit-{completed.returncode}"}
    try:
        rows = json.loads(completed.stdout)
    except json.JSONDecodeError:
        return {"status": "unavailable", "error": "invalid-json"}
    if not isinstance(rows, list):
        return {"status": "unavailable", "error": "invalid-json"}
    names = [str(row.get("name")) for row in rows if isinstance(row, dict)]
    enabled = sorted(str(row.get("name")) for row in rows if isinstance(row, dict) and row.get("enabled") is True)
    return {"status": "ok", "servers": sorted(names), "enabled": enabled}


def codex_office_tools_exercised(text: str) -> list[str]:
    """Office tools the codex process completed (item.completed mcp_tool_call)."""
    used: list[str] = []
    for line in text.splitlines():
        try:
            event = json.loads(line)
        except (json.JSONDecodeError, RecursionError):
            continue
        if not isinstance(event, dict) or event.get("type") != "item.completed":
            continue
        item = event.get("item")
        if not isinstance(item, dict) or item.get("type") != "mcp_tool_call":
            continue
        tool = str(item.get("tool") or "")
        if item.get("server") == CODEX_OFFICE_MCP_SERVER_NAME and item.get("status") == "completed" and tool not in used:
            used.append(tool)
    return used


def opencode_office_mcp_preflight(
    executable: str, workspace: Path, run_dir: Path, office_mcp: dict[str, Any],
    profile: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Run the connection probe in its own guarded home with the run's config."""
    probe_dir = Path(run_dir) / "opencode-mcp-probe"
    probe_dir.mkdir(parents=True, exist_ok=True)
    env = dict(os.environ)
    for key in SENSITIVE_ENV_KEYS:
        env.pop(key, None)
    env.update(prepare_guarded_opencode_environment(probe_dir))
    env["OPENCODE_CONFIG_CONTENT"] = opencode_runtime_config(
        office_mcp=office_mcp, profile=profile
    )
    env["OPENCODE_AUTO_SHARE"] = "false"
    env["OPENCODE_DISABLE_AUTOUPDATE"] = "true"
    return opencode_office_mcp_connection(executable, workspace, env)


def opencode_office_tools_exercised(text: str) -> list[str]:
    """Office tools the run actually completed (OpenCode names them office_<tool>)."""
    used: list[str] = []
    prefix = f"{OFFICE_MCP_SERVER_NAME}_"
    for line in text.splitlines():
        try:
            event = json.loads(line)
        except (json.JSONDecodeError, RecursionError):
            continue
        part = event.get("part") if isinstance(event, dict) else None
        if not isinstance(part, dict) or part.get("type") != "tool":
            continue
        tool = str(part.get("tool") or "")
        state = part.get("state") if isinstance(part.get("state"), dict) else {}
        if tool.startswith(prefix) and state.get("status") == "completed" and tool not in used:
            used.append(tool)
    return used


MODEL_TOOL_SCAN_MAX_NODES = 2000


class ToolEventScanIncomplete(process_supervision.ToolEventUnreadable):
    """An event could not be read in full; its tool ids are unknown.

    Every tool-count path treats this like an unreadable event: the count
    becomes unknown (None), never the lower number reached so far, and the
    live supervisor only warns instead of aborting the run.
    """


def model_tool_event_ids(line: str, adapter_id: str) -> set[str]:
    """Tool ids of one live stdout line for the supervisor.

    A line that is not JSON is not an event (banners, progress text). A
    line that starts like an event ('{') but is not valid JSON is a cut or
    corrupt event, as in the complete-stream parser. It raises
    ToolEventScanIncomplete, and so does an event that json.loads cannot
    finish (RecursionError on model-controlled nesting), that exceeds the
    scan bound or whose fields the scanner cannot handle (TypeError or
    ValueError on an unexpected shape).
    """
    try:
        value = json.loads(line)
    except json.JSONDecodeError as exc:
        if line.lstrip().startswith("{"):
            raise ToolEventScanIncomplete("corrupt or cut event line") from exc
        return set()
    except RecursionError as exc:
        raise ToolEventScanIncomplete("event nesting exceeds the JSON parser") from exc
    try:
        return model_tool_ids_from_event(value, line, adapter_id)
    except ToolEventScanIncomplete:
        raise
    except RecursionError as exc:  # canonical fallback id of a deep block
        raise ToolEventScanIncomplete("event nesting exceeds the JSON encoder") from exc
    except (TypeError, ValueError) as exc:
        # The event is model- and CLI-controlled data: a field of a shape the
        # scanner cannot handle (item.type=[] is unhashable) is an unreadable
        # event, like the complete-stream parser treats it, never an abort.
        raise ToolEventScanIncomplete("event field has an unreadable shape") from exc


def model_tool_ids_from_event(value: Any, line: str, adapter_id: str) -> set[str]:
    if adapter_id == "codex":
        if not isinstance(value, dict) or value.get("type") != "item.started":
            return set()
        item = value.get("item")
        if not isinstance(item, dict) or item.get("type") in {
            None,
            "agent_message",
            "error",
            "reasoning",
        }:
            return set()
        identity = item.get("id") or item.get("call_id")
        return {f"codex:{identity or sha256_text(line)}"}
    if adapter_id != "claude":
        return set()
    found: set[str] = set()
    stack: list[Any] = [value]
    visited = 0
    while stack:
        if visited >= MODEL_TOOL_SCAN_MAX_NODES:
            # A partial walk may have missed tool_use blocks: unknown, not fewer.
            raise ToolEventScanIncomplete(
                f"event exceeds {MODEL_TOOL_SCAN_MAX_NODES} scanned containers")
        current = stack.pop()
        visited += 1
        if isinstance(current, dict):
            current_type = current.get("type")
            if current_type == "tool_use" and current.get("name") != "StructuredOutput":
                identity = current.get("id") or current.get("tool_use_id")
                fallback = sha256_bytes(canonical_json_bytes(current))
                found.add(f"claude:{identity or fallback}")
            elif current_type == "content_block_start":
                block = current.get("content_block")
                if (
                    isinstance(block, dict)
                    and block.get("type") == "tool_use"
                    and block.get("name") != "StructuredOutput"
                ):
                    identity = block.get("id") or block.get("tool_use_id")
                    fallback = sha256_bytes(canonical_json_bytes(block))
                    found.add(f"claude:{identity or fallback}")
            # Only containers can hold a tool_use block; scalars do not
            # spend the scan bound.
            stack.extend(v for v in current.values() if isinstance(v, (dict, list)))
        elif isinstance(current, list):
            stack.extend(v for v in current if isinstance(v, (dict, list)))
    return found


def observed_model_tool_calls(adapter_id: str, stdout: str) -> int | None:
    """Tool calls visible in a complete JSON event stream; None is unknown.

    Codex `exec --json` always streams its item events and Qwen stream-json
    carries Claude-shaped tool_use parts, but the supervisor counts them only
    under a tool budget. Other adapters report their own count (Grok ACP) or
    expose no event stream here, so they stay unknown.

    This runs after the child exited and before stdout and the run record
    are written, so it must never raise: an event it cannot read (tool
    arguments are model-controlled, and json.loads raises RecursionError past
    ~1000 nesting levels) makes the whole count unknown. So does a stream
    that is not complete: a cut or corrupt event line (killed child,
    truncated output), an event wider than the scan bound
    (ToolEventScanIncomplete), no event at all (empty stdout, a crash banner) or a
    stream that never reached its terminal event (Codex turn.completed or
    turn.failed, the stream-json result record) is never reported as a
    known 0 or as a lower count.
    """
    parser = {"codex": "codex", "qwen": "claude"}.get(adapter_id)
    if parser is None:
        return None
    return _json_stream_tool_calls(parser, stdout)


QWEN_NATIVE_BUDGET_LINE = re.compile(
    r"^Run aborted: (?:"
    r"tool-call budget of (?P<tool_limit>\d{1,7}) exceeded \(--max-tool-calls\); observed (?P<tool_observed>\d{1,7})\."
    r"|"
    r"wall-clock budget of (?P<wall_limit>\d{1,7})s exceeded \(--max-wall-time\)\."
    r")$",
    re.MULTILINE,
)


def qwen_native_budget_stop(
    stderr: str | None, exit_code: int | None
) -> dict[str, Any] | None:
    try:
        if type(exit_code) is not int or exit_code != 55:
            return None
        if not isinstance(stderr, str):
            return None
        normalized = stderr.replace("\r\n", "\n")
        last_match = None
        for match in QWEN_NATIVE_BUDGET_LINE.finditer(normalized):
            last_match = match
        if last_match is None:
            return None
        tool_limit = last_match.group("tool_limit")
        if tool_limit is not None:
            return {
                "kind": "tool-calls",
                "limit": int(tool_limit),
                "observed": int(last_match.group("tool_observed")),
            }
        wall_limit = last_match.group("wall_limit")
        if wall_limit is not None:
            return {
                "kind": "wall-clock",
                "limit": int(wall_limit),
                "observed": None,
            }
        return None
    except Exception:
        return None


MODEL_STREAM_TERMINAL_TYPES = {
    "codex": frozenset({"turn.completed", "turn.failed"}),
    "claude": frozenset({"result"}),
}


def _json_stream_tool_calls(parser: str, stdout: str) -> int | None:
    """Tool calls of a complete event stream in `parser` shape, else None."""
    seen: set[str] = set()
    terminal = False
    for line in str(stdout or "").splitlines():
        if line.lstrip().startswith("{"):
            try:
                value = json.loads(line)
                seen |= model_tool_ids_from_event(value, line, parser)
            except (ValueError, TypeError, RecursionError):
                return None
            if isinstance(value, dict) and value.get("type") in MODEL_STREAM_TERMINAL_TYPES[parser]:
                terminal = True
    return len(seen) if terminal else None


def recorded_model_tool_calls(
    adapter_id: str, child: dict[str, Any], stdout: str
) -> int | None:
    """Tool-call count for the run record; None whenever it is not known.

    The supervisor counts Codex/Claude events only under a tool budget and
    returns that count even when the stream was cut. A count that stopped the
    child at the enforced limit is the enforcement evidence and stays. Any
    other supervisor count is kept only for a stream that reached its
    terminal event; a timeout, a supervision failure, a live scan that could
    not read every event or a stream without its terminal record is an
    unknown count, never a known 0 or a lower count.
    Without a supervisor count the complete-stream parser decides.
    """
    count = child.get("model_tool_calls")
    if count is None:
        return observed_model_tool_calls(adapter_id, stdout)
    if adapter_id not in {"codex", "claude"} or child.get("tool_budget_exceeded"):
        return count
    if (
        child.get("timed_out")
        or child.get("supervision_failed")
        or child.get("model_tool_scan_incomplete")
    ):
        return None
    if _json_stream_tool_calls(adapter_id, stdout) is None:
        return None
    return count


# Adapters whose run actually enforces --max-model-tool-calls.
TOOL_BUDGET_ENFORCING_ADAPTERS = frozenset(
    {"codex", "claude", "qwen", "grok", "minimax", "muse", "openclaw", "mistral", "zcode"}
)
OPENCLAW_TOOL_LIMITS_BY_MODE = {"advisory": 8, "review": 12, "implement": 32}
OPENCLAW_READ_CONTEXT_TOKENS = 131_072


def effective_run_limits(
    adapter_id: str,
    command: list[str],
    *,
    complexity: str,
    max_prompt_bytes: int | None,
    max_model_tool_calls: int | None,
    context_window_tokens: Any,
) -> tuple[int | None, int | None]:
    """Prompt-byte and tool-call limits this run actually enforced.

    The record shows what Fleet applied, not only what the caller asked for:
    the context-window send gate bounds the prompt, the OpenClaw envelope caps
    its message, Qwen enforces --max-tool-calls and Grok ACP its default
    budget. A requested tool budget counts only for adapters that enforce it
    (supervisor for Codex/Claude, persisted transcript probe for OpenClaw,
    Qwen settings, Grok ACP, MiniMax and Muse step caps); Kimi and the other
    adapters receive no cap, so their record says None. None only when no
    limit of that kind was applied.
    """
    prompt_limits = [
        value
        for value in (
            max_prompt_bytes,
            routing_v2.context_prompt_byte_limit(context_window_tokens),
            openclaw_runtime.PINNED_OPENCLAW_MAX_MESSAGE_BYTES
            if adapter_id == "openclaw"
            else None,
        )
        if value is not None
    ]
    tool_limit = (
        max_model_tool_calls if adapter_id in TOOL_BUDGET_ENFORCING_ADAPTERS else None
    )
    if adapter_id == "qwen" and "--max-tool-calls" in command[:-1]:
        tool_limit = int(command[command.index("--max-tool-calls") + 1])
        # Local Qwen passes -1 for "no limit": no limit was applied.
        tool_limit = tool_limit if tool_limit >= 0 else None
    elif adapter_id == "grok" and tool_limit is None:
        tool_limit = grok_acp.GROK_TOOL_LIMITS[complexity]
    elif adapter_id in {"minimax", "muse"}:
        # Both always run with a step cap (the requested budget or the
        # per-complexity default); record the cap the argv carries.
        flag = "--max-steps" if adapter_id == "minimax" else "--max-model-steps"
        if flag in command[:-1]:
            tool_limit = int(command[command.index(flag) + 1])
    return (min(prompt_limits) if prompt_limits else None), tool_limit


def terminate_process_tree(process: subprocess.Popen[str]) -> None:
    if process.poll() is not None:
        return
    if os.name == "nt":
        subprocess.run(
            ["taskkill.exe", "/PID", str(process.pid), "/T", "/F"],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
            timeout=15,
        )
        if process.poll() is None:
            process.terminate()
    else:
        process.terminate()
    try:
        process.wait(timeout=5)
    except subprocess.TimeoutExpired:
        process.kill()
        process.wait(timeout=5)


class ReleasableKernelLock:
    def __init__(self, path: Path, *, timeout: float):
        self.path = path
        self.timeout = timeout
        self.handle = None

    def acquire(self) -> float:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        if is_filesystem_link(self.path):
            raise FleetError("Qwen Docker allocation lock cannot be linked")
        started = time.monotonic()
        handle = self.path.open("a+b")
        handle.seek(0, os.SEEK_END)
        if handle.tell() == 0:
            handle.write(b"\0")
            handle.flush()
        handle.seek(0)
        deadline = started + max(0.1, self.timeout)
        try:
            while True:
                try:
                    if os.name == "nt":
                        import msvcrt

                        msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
                    else:
                        import fcntl

                        fcntl.flock(
                            handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB
                        )
                    break
                except OSError as exc:
                    if time.monotonic() >= deadline:
                        raise FleetError(
                            "Qwen Docker launch allocation lock timed out"
                        ) from exc
                    time.sleep(0.05)
        except Exception:
            handle.close()
            raise
        self.handle = handle
        return round(time.monotonic() - started, 6)

    def release(self) -> None:
        handle = self.handle
        if handle is None:
            return
        self.handle = None
        try:
            handle.seek(0)
            if os.name == "nt":
                import msvcrt

                msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl

                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
        finally:
            handle.close()


def resolve_docker_executable(env: dict[str, str]) -> str:
    executable = shutil.which("docker", path=env.get("PATH"))
    if not executable:
        raise FleetError("Qwen Docker launch protection cannot find docker")
    return executable


def qwen_container_ids(docker: str, env: dict[str, str]) -> set[str]:
    try:
        completed = subprocess.run(
            [docker, "ps", "--all", "--format", "{{.ID}}"],
            env=env,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=5,
            check=False,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        raise FleetError("Qwen Docker allocation probe failed") from exc
    if completed.returncode != 0:
        raise FleetError("Qwen Docker allocation probe failed")
    identities = {
        line.strip().casefold()
        for line in completed.stdout.splitlines()
        if line.strip()
    }
    if any(not re.fullmatch(r"[a-f0-9]{8,64}", item) for item in identities):
        raise FleetError("Qwen Docker allocation probe returned malformed identity")
    return identities


def _normalized_docker_path(value: str) -> str:
    text = value.strip().replace("\\", "/").casefold().rstrip("/")
    match = re.match(r"^/(?:host_mnt|run/desktop/mnt/host)/([a-z])/(.*)$", text)
    if match:
        text = f"{match.group(1)}:/{match.group(2)}".rstrip("/")
    return text


def qwen_container_owns_workspace(
    docker: str, container_id: str, workspace: Path, env: dict[str, str]
) -> bool:
    try:
        completed = subprocess.run(
            [docker, "inspect", "--format", "{{json .Mounts}}", container_id],
            env=env,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=5,
            check=False,
        )
        mounts = json.loads(completed.stdout) if completed.returncode == 0 else None
    except (OSError, subprocess.TimeoutExpired, json.JSONDecodeError):
        return False
    if not isinstance(mounts, list):
        return False
    expected = _normalized_docker_path(str(workspace.resolve()))
    for mount in mounts:
        source = mount.get("Source") if isinstance(mount, dict) else None
        if not isinstance(source, str):
            continue
        observed = _normalized_docker_path(source)
        if observed and (
            observed == expected
            or expected.startswith(observed + "/")
            or observed.startswith(expected + "/")
        ):
            return True
    return False


class QwenDockerLaunchAllocation:
    """Serialize only Docker name allocation/start, never the cloud task."""

    def __init__(self, root: Path, workspace: Path, env: dict[str, str], timeout: int):
        locks = guarded_state_directory(
            root, "locks", "qwen-docker-launch", create=True
        )
        self.lock = ReleasableKernelLock(
            locks / "allocation.lock", timeout=min(float(timeout), 30.0)
        )
        self.workspace = workspace
        self.env = env
        self.timeout = timeout
        self.docker = ""
        self.before: set[str] = set()
        self.lock_wait_seconds = 0.0
        self.confirmed: dict[str, Any] | None = None

    def __enter__(self) -> "QwenDockerLaunchAllocation":
        self.docker = resolve_docker_executable(self.env)
        self.lock_wait_seconds = self.lock.acquire()
        try:
            self.before = qwen_container_ids(self.docker, self.env)
        except Exception:
            self.lock.release()
            raise
        return self

    def confirm(self, process: subprocess.Popen[str]) -> dict[str, Any]:
        started = time.monotonic()
        deadline = started + min(
            float(self.timeout), float(QWEN_DOCKER_CONFIRM_TIMEOUT_SECONDS)
        )
        while time.monotonic() < deadline:
            current = qwen_container_ids(self.docker, self.env)
            for container_id in sorted(current - self.before):
                if qwen_container_owns_workspace(
                    self.docker, container_id, self.workspace, self.env
                ):
                    self.confirmed = {
                        "status": "confirmed",
                        "allocation_wait_seconds": self.lock_wait_seconds,
                        "confirmation_seconds": round(
                            time.monotonic() - started, 6
                        ),
                        "container_fingerprint": sha256_text(container_id),
                    }
                    self.lock.release()
                    return self.confirmed
            if process.poll() is not None:
                self.confirmed = {
                    "status": "process-exited-before-container",
                    "allocation_wait_seconds": self.lock_wait_seconds,
                    "confirmation_seconds": round(time.monotonic() - started, 6),
                    "container_fingerprint": None,
                }
                self.lock.release()
                return self.confirmed
            time.sleep(QWEN_DOCKER_POLL_SECONDS)
        self.lock.release()
        raise FleetError("Qwen Docker launch allocation was not confirmed")

    def __exit__(self, exc_type: Any, exc: Any, traceback: Any) -> None:
        self.lock.release()


def run_bounded_child(
    command: list[str],
    *,
    cwd: Path,
    env: dict[str, str],
    stdin_text: str | None,
    timeout: int,
    adapter_id: str,
    max_model_tool_calls: int | None,
    launch_observer: Callable[[subprocess.Popen[str]], dict[str, Any]] | None = None,
    max_context_tokens: int | None = None,
    checkpoint_path: Path | None = None,
) -> dict[str, Any]:
    import process_supervision

    if max_context_tokens is not None and adapter_id not in {"mimo", "antigravity", "opencode"}:
        raise FleetError("Measured context stop is only verified for MiMo/Antigravity/OpenCode streams")
    tool_limit = max_model_tool_calls if adapter_id in {"codex", "claude", "openclaw"} else None
    tool_probe = None
    if adapter_id == "openclaw" and tool_limit is not None:
        if "--state-dir" not in command[:-1]:
            raise FleetError("OpenClaw tool budget requires a pinned --state-dir")
        state_dir = Path(command[command.index("--state-dir") + 1])
        openclaw_runtime.assert_run_owned_state_dir(state_dir)
        tool_probe = lambda: openclaw_runtime.transcript_tool_call_count(state_dir)
    progress_probe = None
    progress_stall_seconds = None
    if adapter_id == "mistral" and checkpoint_path is not None:
        run_dir = Path(checkpoint_path).parent
        stall = mistral_runtime.native_stall_seconds(timeout)
        if stall is not None:
            progress_probe = mistral_runtime.native_progress_probe(run_dir)
            progress_stall_seconds = stall
    child = process_supervision.run(
        command, cwd=cwd, env=env, stdin_text=stdin_text, timeout=timeout,
        tool_limit=tool_limit,
        tool_events=(None if adapter_id == "openclaw"
                     else lambda line: model_tool_event_ids(line, adapter_id)),
        launch_observer=launch_observer,
        tool_count_probe=tool_probe,
        context_limit=max_context_tokens,
        context_tokens=(
            mimo_stream_context_tokens if adapter_id == "mimo"
            else antigravity_stream_context_tokens if adapter_id == "antigravity"
            else opencode_max_distinct_step_context_tokens()
        ) if max_context_tokens is not None else None,
        context_fail_closed=(max_context_tokens is not None and adapter_id == "opencode"),
        context_oversized_critical=(
            opencode_oversized_line_is_usage
            if max_context_tokens is not None and adapter_id == "opencode" else None
        ),
        checkpoint_path=checkpoint_path,
        terminal_completion=minimax_terminal_completion if adapter_id == "minimax" else None,
        progress_probe=progress_probe,
        progress_stall_seconds=progress_stall_seconds,

    )
    if adapter_id == "minimax":
        child = minimax_fold_child_stdout(child)
    return child


def run_provider_child(
    command: list[str],
    *,
    cwd: Path,
    env: dict[str, str],
    stdin_text: str | None,
    timeout: int,
    adapter_id: str,
    max_model_tool_calls: int | None,
    local_runtime: dict[str, Any] | None = None,
    local_execution_capacity: int | None = None,
    state_root: Path | None = None,
    max_context_tokens: int | None = None,
    checkpoint_path: Path | None = None,
) -> dict[str, Any]:
    protect_qwen_launch = adapter_id == "qwen" and "--sandbox" in command

    def invoke_child() -> tuple[dict[str, Any], dict[str, Any] | None, float]:
        if not protect_qwen_launch:
            child = run_bounded_child(
                command,
                cwd=cwd,
                env=env,
                stdin_text=stdin_text,
                timeout=timeout,
                adapter_id=adapter_id,
                max_model_tool_calls=max_model_tool_calls,
                max_context_tokens=max_context_tokens,
                checkpoint_path=checkpoint_path,
            )
            return child, None, 0.0
        if state_root is None:
            raise FleetError("Qwen Docker launch protection requires Fleet state root")
        with QwenDockerLaunchAllocation(state_root, cwd, env, timeout) as allocation:
            child = run_bounded_child(
                command,
                cwd=cwd,
                env=env,
                stdin_text=stdin_text,
                timeout=timeout,
                adapter_id=adapter_id,
                max_model_tool_calls=max_model_tool_calls,
                launch_observer=allocation.confirm,
                max_context_tokens=max_context_tokens,
                checkpoint_path=checkpoint_path,
            )
        launch = child.get("launch_protection") or allocation.confirmed
        return child, launch, allocation.lock_wait_seconds

    if local_runtime is None:
        child, launch_protection, allocation_wait = invoke_child()
        return {
            "child": child,
            "queue_wait_seconds": allocation_wait,
            "execution_seconds": float(child.get("execution_seconds", 0.0)),
            "execution_serialized": False,
            "execution_capacity": None,
            "execution_slot_index": None,
            "launch_protection": launch_protection,
        }

    wait_started = time.monotonic()
    try:
        with local_runtime_execution_lock(
            local_runtime,
            timeout=timeout,
            capacity=local_execution_capacity,
        ) as execution_slot:
            local_wait_seconds = round(time.monotonic() - wait_started, 6)
            child, launch_protection, allocation_wait = invoke_child()
            queue_wait_seconds = round(local_wait_seconds + allocation_wait, 6)
    except FleetError as exc:
        raise FleetError(f"Local Qwen execution queue failed: {exc}") from exc
    return {
        "child": child,
        "queue_wait_seconds": queue_wait_seconds,
        "execution_serialized": int(execution_slot["max_num_seqs"]) == 1,
        "execution_capacity": int(execution_slot["max_num_seqs"]),
        "execution_slot_index": int(execution_slot["slot_index"]),
        "execution_seconds": float(child.get("execution_seconds", 0.0)),
        "launch_protection": launch_protection,
    }


# Raw pipe capture is capped. Display slices are not a memory bound: a reader
# that keeps appending after the probe returns retains every later byte.
_PROBE_CAPTURE_BYTES = 65536


class _ProbeByteCapture:
    """Bounded buffer for one probe pipe.

    Bytes past ``limit`` are discarded. ``abandon()`` drops retained bytes and
    tells the reader to stop so a descendant that still writes cannot grow this
    buffer after a timeout return. The reader closes its own stream.
    """

    def __init__(self, limit: int) -> None:
        if limit < 1:
            raise ValueError("probe capture limit must be positive")
        self.limit = limit
        self.peak = 0
        self._chunks: list[bytes] = []
        self._abandoned = False
        self._lock = threading.Lock()

    @property
    def retained(self) -> int:
        with self._lock:
            return sum(len(part) for part in self._chunks)

    def abandoned(self) -> bool:
        with self._lock:
            return self._abandoned

    def add(self, data: bytes) -> bool:
        """Retain ``data`` up to the limit. False means nothing further is kept."""
        if not data:
            return True
        with self._lock:
            if self._abandoned:
                return False
            current = sum(len(part) for part in self._chunks)
            if current >= self.limit:
                return False
            piece = data[: self.limit - current]
            if piece:
                self._chunks.append(piece)
                current += len(piece)
            if current > self.peak:
                self.peak = current
            return current < self.limit

    def snapshot(self) -> bytes:
        with self._lock:
            return b"".join(self._chunks)

    def abandon(self) -> None:
        with self._lock:
            self._abandoned = True
            self._chunks.clear()


def _read_probe_stream(stream: Any, capture: _ProbeByteCapture) -> None:
    """Drain raw pipe bytes until EOF, error, or ``capture.abandon()``.

    Closes ``stream`` before returning. A still-full capture is not EOF: the
    read end stays open so a noisy child can finish and exit 0. Closing this
    stream from any other thread can deadlock a blocked ``os.read`` on Windows.
    """
    try:
        fd = stream.fileno()
        while not capture.abandoned():
            data = os.read(fd, 4096)
            if not data:
                break
            capture.add(data)
    except (OSError, ValueError):
        pass
    finally:
        try:
            if not getattr(stream, "closed", False):
                stream.close()
        except (OSError, ValueError):
            pass


def _terminate_probe_child(proc: subprocess.Popen[bytes]) -> None:
    """Stop only the direct child. Descendants that inherited its pipes are left alone."""
    if proc.poll() is not None:
        return
    try:
        proc.kill()
    except OSError:
        pass
    try:
        proc.wait(timeout=0.2)
    except (OSError, subprocess.TimeoutExpired):
        pass


def probe_command(
    executable: str,
    args: list[str],
    *,
    timeout: int | float = 20,
    cwd: Path | None = None,
    env: dict[str, str] | None = None,
    profile: dict[str, Any] | None = None,
) -> dict[str, Any]:
    mercury_probe = is_mercury_profile(profile)
    if mercury_probe:
        if not mercury_probe or cwd is None or env is None:
            raise FleetError("Mercury native probe requires explicit admission and isolated environment")
        qualify_mercury_workspace(profile, cwd)
        runtime = mercury_runtime_module()
        runtime.require_native(executable)
        if args not in (["--version"], ["models", "inception"]):
            raise FleetError("Mercury probe arguments refused")
    started = time.monotonic()
    deadline = started + float(timeout)
    proc: subprocess.Popen[bytes] | None = None
    out_capture: _ProbeByteCapture | None = None
    err_capture: _ProbeByteCapture | None = None
    readers_started = False
    try:
        proc = subprocess.Popen(
            [executable, *args],
            cwd=str(cwd) if cwd else None,
            env=env
            or sanitized_environment(inherit_api_keys=False, native_subagent_limit=0),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            creationflags=subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0,
        )
        out_capture = _ProbeByteCapture(_PROBE_CAPTURE_BYTES)
        err_capture = _ProbeByteCapture(_PROBE_CAPTURE_BYTES)
        # stdout/stderr are owned by these threads. Do not close them here.
        # Once readers exist they own the pipes. A later start() failure must
        # not make the parent close a stream blocked in os.read.
        readers_started = True
        threading.Thread(
            target=_read_probe_stream, args=(proc.stdout, out_capture), daemon=True
        ).start()
        threading.Thread(
            target=_read_probe_stream, args=(proc.stderr, err_capture), daemon=True
        ).start()

        # subprocess.run completion is process exit AND stdout/stderr EOF.
        # One deadline covers both. Parent exit with an inherited write handle
        # still open is not success and must not wait out the descendant.
        while True:
            exited = proc.poll() is not None
            pipes_done = _probe_pipes_done(proc)
            if exited and pipes_done:
                break
            if time.monotonic() >= deadline:
                raise subprocess.TimeoutExpired([executable, *args], timeout)
            time.sleep(0.01)

        returncode = proc.poll()
        if returncode is None:
            raise subprocess.TimeoutExpired([executable, *args], timeout)
        raw_stdout = (
            out_capture.snapshot().decode("utf-8", errors="replace").replace("\r\n", "\n")
        )
        raw_stderr = (
            err_capture.snapshot().decode("utf-8", errors="replace").replace("\r\n", "\n")
        )
        if mercury_probe:
            secret = env.get("INCEPTION_API_KEY")
            raw_stdout = runtime.scrub_output(raw_stdout or "", (secret,))
            raw_stderr = runtime.scrub_output(raw_stderr or "", (secret,))
        output = (raw_stdout or raw_stderr).strip()
        return {
            "launchable": returncode == 0,
            "exit_code": returncode,
            "output": output[:4000],
            "error": None
            if returncode == 0
            else (raw_stderr.strip()[:2000]),
            "duration_seconds": round(time.monotonic() - started, 3),
        }
    except (OSError, subprocess.TimeoutExpired) as exc:
        if proc is not None and proc.poll() is None:
            _terminate_probe_child(proc)
        if out_capture is not None:
            out_capture.abandon()
        if err_capture is not None:
            err_capture.abandon()
        if proc is not None and not readers_started:
            for stream in (proc.stdout, proc.stderr):
                if stream is not None and not getattr(stream, "closed", False):
                    try:
                        stream.close()
                    except (OSError, ValueError):
                        pass
        return {
            "launchable": False,
            "exit_code": None,
            "output": "",
            "error": f"{type(exc).__name__}: {exc}",
            "duration_seconds": round(time.monotonic() - started, 3),
        }


def _probe_pipes_done(proc: subprocess.Popen[bytes]) -> bool:
    """True when both pipe readers have released their streams."""
    for stream in (proc.stdout, proc.stderr):
        if stream is not None and not stream.closed:
            return False
    return True


