def parse_output_root(value: str | None) -> Path | None:
    return Path(value).expanduser().resolve() if value else None


def completed_run_status(
    exit_code: int,
    handoff: dict[str, Any] | None,
    *,
    adapter_id: str = "generic",
    terminal_reason: str | None = None,
    timed_out: bool = False,
    semantic_error: str | None = None,
    progress_stalled: bool = False,
    tool_budget_exceeded: bool = False,
    stdout: str | None = None,
) -> str:
    transport = provider_transport_outcome(
        adapter_id,
        stdout=stdout,
        exit_code=exit_code,
        terminal_reason=terminal_reason,
        timed_out=timed_out,
        handoff_valid=handoff is not None and semantic_error is None,
        progress_stalled=progress_stalled,
        tool_budget_exceeded=tool_budget_exceeded,



    )
    if transport["status"] == "partial":
        return "PARTIAL"
    if transport["status"] != "complete" or handoff is None or semantic_error:
        return "FAILED"
    handoff_status = str(handoff.get("status", "failed")).upper()
    return (
        handoff_status
        if handoff_status in {"COMPLETED", "PARTIAL", "BLOCKED"}
        else "FAILED"
    )


def completed_council_status(results: list[dict[str, Any]], *, dry_run: bool) -> str:
    if dry_run:
        return "DRY_RUN"
    statuses = [str(result.get("status", "FAILED")) for result in results]
    if statuses and all(status == "COMPLETED" for status in statuses):
        return "COMPLETED"
    if statuses and all(status == "BLOCKED" for status in statuses):
        return "BLOCKED"
    if any(status in {"COMPLETED", "PARTIAL", "BLOCKED"} for status in statuses):
        return "PARTIAL"
    return "FAILED"


def result_exit_code(result: dict[str, Any]) -> int:
    """Map a structured top-level result to the documented process exit code."""
    status = str(result.get("status") or result.get("run_status") or "").upper()
    if status == "REFUSED":
        return EXIT_REFUSED
    if status == "FAILED":
        return EXIT_EXECUTION_FAILED
    auditor_run = result.get("auditor_run")
    if isinstance(auditor_run, dict):
        nested = str(
            auditor_run.get("status") or auditor_run.get("run_status") or ""
        ).upper()
        if nested == "FAILED":
            return EXIT_EXECUTION_FAILED
    return EXIT_SUCCESS


def choose_agent(
    requested: str,
    task: str,
    *,
    profiles: dict[str, dict[str, Any]],
    kind: str,
    complexity: str,
    root: Path,
    cwd: Path,
    assessment_file: str | None = None,
    mode: str = "advisory",
    force_delegation: bool = False,
    override_pace_brake: bool = False,
) -> tuple[str, str, dict[str, Any]]:
    route = route_task(
        task,
        profiles=profiles,
        kind=kind,
        complexity=complexity,
        root=root,
        cwd=cwd,
        allow_no_eligible=requested != "auto",
        assessment_file=assessment_file,
        mode=mode,
        force_delegation=force_delegation,
        requested_agent=requested if requested != "auto" else None,
        allow_synthetic_worker=mode == "implement",
    )
    selected_kind = str(route["selected_kind"])
    if route.get("status") == "SKIPPED":
        return "", selected_kind, route
    if requested == "auto":
        return str(route["selected_agent"]), selected_kind, route
    if requested not in profiles:
        raise FleetError(f"Unknown requested agent: {requested}")
    row = next(item for item in route["rankings"] if item["agent"] == requested)
    synthetic_explicit = is_beam_profile(profiles.get(requested))
    selected_execution = row.get("selected_execution_profile")
    explicit_canary = bool(
        isinstance(selected_execution, dict)
        and routing_v2.permits_explicit_canary(
            selected_execution, row.get("gate_results", [])
        )
    )
    failed_gates = {
        str(gate["code"]) for gate in row.get("gate_results", [])
        if not bool(gate["passed"])
    }
    brake_only_override = (
        override_pace_brake and failed_gates == {"pace-brake-clear"}
        and not any(str(reason).startswith("below_quality_floor")
                    for reason in row.get("reasons", []))
    )
    hard_gated = (
        bool(row.get("gate_results"))
        and not bool(row["eligible"])
        and not explicit_canary
        and not brake_only_override
    )
    if not synthetic_explicit and (not row["launchable"] or hard_gated):
        brake = route.get("quota_snapshots", {}).get(requested, {}).get("pace_brake")
        brake = brake if isinstance(brake, dict) else {}
        brake_detail = (
            f"; reason={brake.get('reason')}; until={brake.get('until')}"
            if "pace-brake-clear" in failed_gates else ""
        )
        readiness_row = route.get("readiness", {}).get(requested, {})
        refusals = [
            str(reason) for reason in readiness_row.get("reasons", [])
            if str(reason).startswith("availability-blocked=")
        ] if isinstance(readiness_row, dict) else []
        raise FleetError(
            f"Requested agent {requested} is unavailable or fails hard gates: "
            + ", ".join([*row["reasons"], *refusals])
            + brake_detail
        )
    route["auto_selected_agent"] = route["selected_agent"]
    route["auto_selected_model"] = route["selected_model"]
    route["selected_agent"] = requested
    route["selected_model"] = row["suggested_model"]
    route["selected_execution_profile"] = row.get("selected_execution_profile")
    route["selected_execution_profile_id"] = row.get("execution_profile_id")
    route["assignment_score"] = row.get("assignment_score")
    route["gate_results"] = row.get("gate_results", [])
    route["explicit_canary_override"] = explicit_canary
    route["selection_note"] = (
        f"Explicit synthetic-only profile: {requested}"
        if synthetic_explicit
        else f"Explicit agent override: {requested}; quality-floor override"
        if not row["eligible"]
        else f"Explicit agent override: {requested}"
    )
    if row.get("billing_last_resort"):
        route["selection_note"] += "; conscious billing last-resort override"
    return requested, selected_kind, route


def validate_model_name(value: str) -> str:
    model = value.strip()
    if (
        not model
        or model.startswith("-")
        or len(model) > 256
        or any(char in model for char in "\r\n\0")
    ):
        raise FleetError("Model override is empty or malformed")
    return model


def configured_models(profile: dict[str, Any], suggested: str) -> list[str]:
    models: list[str] = []
    execution_models = [
        row["model"]
        for row in profile.get("execution_profiles", {}).values()
        if isinstance(row, dict)
        and str(row.get("lifecycle", "ACTIVE")).upper() in routing_v2.ACTIVE_LIFECYCLES
    ]
    for candidate in [suggested, *execution_models, *profile["models"].values()]:
        model = validate_model_name(str(candidate))
        if model not in models:
            models.append(model)
    return models


def validate_configured_model(
    profile_id: str, profile: dict[str, Any], value: str
) -> str:
    model = validate_model_name(value)
    if model not in routing_v2.configured_models(profile):
        raise FleetError(f"Model {model} is not configured for {profile_id}")
    return model


def execution_profile_owner(
    profiles: dict[str, dict[str, Any]], execution_profile_id: str
) -> str | None:
    """First agent (sorted) that defines the given execution profile."""
    owners = sorted(
        agent_id
        for agent_id, profile in profiles.items()
        if execution_profile_id in profile.get("execution_profiles", {})
    )
    return owners[0] if owners else None


def validate_auditor_model(
    profiles: dict[str, dict[str, Any]],
    *,
    auditor: str,
    auditor_model: str | None,
) -> str | None:
    """Accept the documented model identifier form or fail with allowed values."""
    if auditor_model is None:
        return None
    if auditor == "auto":
        raise FleetError("--auditor-model requires an explicit --auditor")
    if auditor not in profiles:
        raise FleetError(f"Unknown quality auditor: {auditor}")
    model = validate_model_name(auditor_model)
    allowed = sorted(routing_v2.configured_models(profiles[auditor]))
    if model not in allowed:
        raise FleetError(
            f"--auditor-model {model} is not configured for auditor {auditor}; "
            "the expected field is the auditor execution-profile `model` "
            f"identifier; allowed values: {', '.join(allowed) or '<none>'}"
        )
    return model


def council_member(
    profile_id: str,
    model: str,
    row: dict[str, Any],
    *,
    quality_override: bool,
) -> dict[str, Any]:
    return {
        "id": f"{profile_id}@{model}",
        "agent": profile_id,
        "adapter": row["adapter"],
        "model": model,
        "fit": row["fit"],
        "quality_floor": row["quality_floor"],
        "quality_override": quality_override,
    }


def select_council_members(
    route: dict[str, Any],
    profiles: dict[str, dict[str, Any]],
    *,
    mode: str,
    requested: str,
    count: int | None,
    all_models: bool,
) -> list[dict[str, Any]]:
    row_map = {str(row["agent"]): row for row in route["rankings"]}
    if requested == "auto":
        candidates: list[dict[str, Any]] = []
        for row in route["rankings"]:
            profile_id = str(row["agent"])
            if (
                not row["eligible"]
                or is_beam_profile(profiles.get(profile_id))
                or mode not in profiles[profile_id]["supported_modes"]
            ):
                continue
            models = (
                configured_models(profiles[profile_id], str(row["suggested_model"]))
                if all_models
                else [validate_model_name(str(row["suggested_model"]))]
            )
            models = [
                model for model in models
                if fleet_deny_guard.catalog_decision(profile_id, model)["status"]
                not in {"denied", "unavailable"}
            ]
            candidates.extend(
                council_member(profile_id, model, row, quality_override=False)
                for model in models
            )
        effective_count = (
            count if count is not None else (len(candidates) if all_models else 2)
        )
        if effective_count < 2:
            raise FleetError("A council requires at least two members")
        if effective_count > len(candidates):
            raise FleetError(
                f"Requested council has {effective_count} seats but only "
                f"{len(candidates)} model members are eligible"
            )
        candidate_ids = [str(member["id"]) for member in candidates]
        if len(candidate_ids) != len(set(candidate_ids)):
            raise FleetError("Auto council members must be unique profile@model pairs")
        return candidates[:effective_count]

    if all_models:
        raise FleetError("--all-models can be combined only with --agents auto")
    specs = [item.strip() for item in requested.split(",") if item.strip()]
    effective_count = count if count is not None else len(specs)
    if effective_count < 2:
        raise FleetError("A council requires at least two members")
    if len(specs) != effective_count:
        raise FleetError("Explicit --agents must contain exactly --count members")
    selected: list[dict[str, Any]] = []
    for spec in specs:
        profile_id, separator, requested_model = spec.partition("@")
        profile_id = profile_id.strip()
        row = row_map.get(profile_id)
        if row is None:
            raise FleetError(f"Unknown council profile: {profile_id}")
        if is_beam_profile(profiles.get(profile_id)):
            raise FleetError("Synthetic-only profiles cannot be council members")
        if not row["launchable"]:
            raise FleetError(
                f"Council profile {profile_id} is unavailable or routing-disabled"
            )
        if row.get("gate_results") and not row["eligible"]:
            raise FleetError(
                f"Council profile {profile_id} fails hard routing gates: "
                + ", ".join(row.get("gate_failures", []))
            )
        if mode not in profiles[profile_id]["supported_modes"]:
            raise FleetError(
                f"Council profile {profile_id} does not support safe {mode} mode"
            )
        model = validate_configured_model(
            profile_id,
            profiles[profile_id],
            requested_model if separator else str(row["suggested_model"]),
        )
        try:
            fleet_deny_guard.require_catalog_allowed(profile_id, model)
        except (
            fleet_deny_guard.CatalogModelDenied,
            fleet_deny_guard.CatalogPolicyUnavailable,
        ) as exc:
            raise FleetError(str(exc)) from exc
        selected.append(
            council_member(
                profile_id,
                model,
                row,
                quality_override=not bool(row["eligible"]),
            )
        )
    member_ids = [str(member["id"]) for member in selected]
    if len(member_ids) != len(set(member_ids)):
        raise FleetError("Explicit council members must be unique profile@model pairs")
    return selected


def resolve_native_subagent_limit(
    *,
    complexity: str,
    explicit_limit: int | None,
    legacy_allow: bool,
    agent_id: str | None = None,
) -> int:
    return int(
        resolve_native_subagent_policy(
            complexity=complexity,
            explicit_limit=explicit_limit,
            legacy_allow=legacy_allow,
            agent_id=agent_id,
        )["limit"]
    )


def resolve_native_subagent_policy(
    *,
    complexity: str,
    explicit_limit: int | None,
    legacy_allow: bool,
    agent_id: str | None,
) -> dict[str, Any]:
    if agent_id == SYNTHETIC_ONLY_PROFILE_ID and (
        legacy_allow or (explicit_limit is not None and explicit_limit > 0)
    ):
        raise FleetError("Beam native subagents are disabled")
    if agent_id in {"qwen-local", "qwen-local-5070ti"} and (
        legacy_allow or (explicit_limit is not None and explicit_limit > 0)
    ):
        raise FleetError(
            "local Qwen runtime forbids native subagents; shared capacity is one"
        )
    if explicit_limit is not None and (
        explicit_limit < 0 or explicit_limit > MAX_NATIVE_SUBAGENTS_PER_CONTRACTOR
    ):
        raise FleetError(
            "--native-subagent-limit must be between 0 and "
            f"{MAX_NATIVE_SUBAGENTS_PER_CONTRACTOR}"
        )
    if explicit_limit is None:
        if legacy_allow:
            limit = 4
            source = "explicit-allow-flag"
        elif agent_id in DEFAULT_DENY_NATIVE_SUBAGENT_AGENTS:
            limit = 0
            source = "provider-default-deny"
        else:
            limit = {"low": 0, "medium": 2, "high": 6}[complexity]
            source = "adaptive-default"
    else:
        limit = explicit_limit
        source = "explicit-limit"
    return {
        "agent": agent_id,
        "limit": limit,
        "decision_source": source,
        "explicit_opt_in": limit > 0 and (explicit_limit is not None or legacy_allow),
    }


def resolve_web_access(*, kind: str, web_mode: str | None) -> bool:
    if web_mode == "enabled":
        return True
    if web_mode == "disabled":
        return False
    return kind == "research"


def optional_bool(value: str) -> bool | None:
    if value == "yes":
        return True
    if value == "no":
        return False
    return None


def validate_trace_id(
    value: str | None, *, pattern: re.Pattern[str], label: str
) -> str | None:
    if value is not None and not pattern.fullmatch(value):
        raise FleetError(f"{label} is malformed")
    return value


def add_task_args(parser: argparse.ArgumentParser) -> None:
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("--task")
    group.add_argument("--task-file")
    parser.add_argument(
        "--kind", choices=["auto", *sorted(VALID_KINDS)], default="auto"
    )
    parser.add_argument(
        "--complexity", choices=sorted(VALID_COMPLEXITIES), default="medium"
    )
    parser.add_argument(
        "--assessment-file",
        help="Transport assessment generated by the TODO bridge; optional explicit input for direct legacy CLI calls, not a separate planning contract",
    )


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Route and invoke bounded local AI coding CLI workers."
    )
    parser.add_argument("--version", action="version", version=f"agent-fleet {VERSION}")
    parser.add_argument("--profiles", default=str(DEFAULT_PROFILES))
    parser.add_argument("--state-dir")
    subparsers = parser.add_subparsers(dest="action", required=True)
    policy_parser = subparsers.add_parser("delegation-policy", help="Local direct/compact/full decision without model/readiness calls")
    policy_parser.add_argument("--scope-file", required=True)
    lane_parser = subparsers.add_parser(
        "lane-policy", help="Deterministic adaptive lane evaluation without provider calls"
    )
    lane_parser.add_argument("--request-file", required=True)

    doctor = subparsers.add_parser("doctor", help="Probe CLI readiness without a task")
    doctor.add_argument("--deep", action="store_true")

    status = subparsers.add_parser("status", help="Show local usage metadata")
    status.add_argument("--days", type=int, default=7)
    subparsers.add_parser(
        "incident-report", help="Show the bounded local incident index"
    )

    quota_record = subparsers.add_parser(
        "quota-record", help="Append a source-attributed plan/quota snapshot"
    )
    quota_record.add_argument("--agent", required=True)
    quota_record.add_argument("--short-remaining-pct", type=float)
    quota_record.add_argument("--weekly-remaining-pct", type=float)
    quota_record.add_argument("--monthly-remaining-pct", type=float)
    quota_record.add_argument("--credits-remaining", type=float)
    quota_record.add_argument("--short-reset-at")
    quota_record.add_argument("--weekly-reset-at")
    quota_record.add_argument("--monthly-reset-at")
    quota_record.add_argument("--observed-at")
    quota_record.add_argument(
        "--source", choices=sorted(adaptive.VALID_QUOTA_SOURCES), required=True
    )
    quota_record.add_argument("--confidence", type=float, default=0.8)
    quota_record.add_argument("--note", default="")
    quota_record.add_argument("--valid-for-hours", type=int, default=24)

    subparsers.add_parser("quota-status", help="Show latest quota state per CLI")
    recheck = subparsers.add_parser('availability-recheck', help='One explicit content-free native check; no task dispatch')
    recheck.add_argument('--agent', required=True, choices=['muse', 'codebuddy'])

    reparse_usage = subparsers.add_parser(
        "reparse-usage",
        help="Reparse preserved provider stdout and append an auditable token revision",
    )
    reparse_usage.add_argument("--run-id", required=True)

    reparse_handoff = subparsers.add_parser(
        "reparse-handoff", help="Write an immutable Codex terminal-handoff projection without changing the run"
    )
    reparse_handoff.add_argument("--run-id", required=True)
    reparse_handoff.add_argument("--expected-record-sha256", required=True)
    reparse_handoff.add_argument("--expected-stdout-sha256", required=True)

    accept = subparsers.add_parser(
        "accept", help="Record the parent verification outcome for one Fleet run"
    )
    accept.add_argument("--run-id", required=True)
    accept.add_argument("--quality", type=int, required=True)
    accept.add_argument("--criteria-pass", choices=["yes", "no"], required=True)
    accept.add_argument("--note", default="")
    accept.add_argument(
        "--first-pass", choices=["yes", "no", "unknown"], default="unknown"
    )
    accept.add_argument(
        "--tests-pass", choices=["yes", "no", "unknown"], default="unknown"
    )
    accept.add_argument(
        "--reviewer-accepted", choices=["yes", "no", "unknown"], default="unknown"
    )
    accept.add_argument("--repair-count", type=int)
    accept.add_argument("--human-review-minutes", type=float)
    accept.add_argument("--delegation-prep-minutes", type=float)
    accept.add_argument(
        "--reopened-7d", choices=["yes", "no", "unknown"], default="unknown"
    )
    accept.add_argument("--instruction-compliance", type=int)
    accept.add_argument("--scope-control", type=int)
    accept.add_argument("--code-quality", type=int)
    accept.add_argument("--visual-quality", type=int)
    accept.add_argument("--regressions-found", type=int)
    accept.add_argument("--failure-class")

    outcome = subparsers.add_parser(
        "outcome",
        help="Append a delayed reopen/regression outcome without overwriting acceptance",
    )
    outcome.add_argument("--run-id", required=True)
    outcome.add_argument(
        "--reopened-7d", choices=["yes", "no", "unknown"], default="unknown"
    )
    outcome.add_argument("--regressions-found", type=int)
    outcome.add_argument("--note", default="")

    quality_gate = subparsers.add_parser(
        "quality-gate",
        help="Run one independent read-only auditor over one or more worker runs",
    )
    quality_gate.add_argument("--contract", required=True)
    quality_gate.add_argument("--run-id", action="append", required=True)
    quality_gate.add_argument("--previous-gate-id")
    quality_gate.add_argument("--auditor", default="auto")
    quality_gate.add_argument("--auditor-model")
    quality_gate.add_argument(
        "--complexity", choices=sorted(VALID_COMPLEXITIES), default="medium"
    )
    quality_gate.add_argument("--workspace", default=str(Path.cwd()))
    quality_gate.add_argument("--timeout", type=int, default=900)
    quality_gate.add_argument("--dry-run", action="store_true")
    quality_gate.add_argument("--output-dir")
    quality_gate.add_argument("--assessment-file", default=None)
    quality_gate.add_argument("--supplemental-evidence", help="Explicit workspace-relative file/hash manifest and additive maker provenance")
    quality_gate.add_argument(
        "--public-source-manifest",
        help="Optional worker/path/SHA-256/raw.githubusercontent.com manifest for public-source classification",
    )
    quality_gate.add_argument(
        "--complementary-review", action="store_true",
        help="Independent functional product review in addition to required security; cannot replace security acceptance",
    )

    security_gate = subparsers.add_parser(
        "security-gate",
        help="Run a bounded independent security-review failover over worker runs",
    )
    security_gate.add_argument("--contract", required=True)
    security_gate.add_argument("--run-id", action="append", required=True)
    security_gate.add_argument("--previous-gate-id")
    security_gate.add_argument("--auditor", default="auto")
    security_gate.add_argument("--auditor-model")
    security_gate.add_argument(
        "--complexity", choices=sorted(VALID_COMPLEXITIES), default="medium"
    )
    security_gate.add_argument("--workspace", default=str(Path.cwd()))
    security_gate.add_argument("--timeout", type=int, default=1200)
    security_gate.add_argument("--dry-run", action="store_true")
    security_gate.add_argument("--output-dir")
    security_gate.add_argument("--assessment-file", default=None)
    security_gate.add_argument("--supplemental-evidence", help="Explicit workspace-relative file/hash manifest and additive maker provenance")
    security_gate.add_argument(
        "--public-source-manifest",
        help="Optional worker/path/SHA-256/raw.githubusercontent.com manifest for public-source classification",
    )

    quality_repair = subparsers.add_parser(
        "quality-repair",
        help="Dispatch bounded repairs for REPAIR items and preserve root-task lineage",
    )
    quality_repair.add_argument("--gate-id", required=True)
    quality_repair.add_argument("--timeout", type=int, default=900)
    quality_repair.add_argument("--dry-run", action="store_true")
    quality_repair.add_argument("--output-dir")
    quality_repair.add_argument(
        "--max-model-tool-calls", type=int,
        help="Explicit per-repair native tool-call bound, 1..256; omitted keeps the profile default",
    )

    quality_status = subparsers.add_parser(
        "quality-status", help="Show one Fleet Quality Gate record"
    )
    quality_status.add_argument("--gate-id", required=True)

    campaign_validate = subparsers.add_parser(
        "campaign-validate",
        help="Validate a runnable parent-gated scientific campaign and experiment card",
    )
    campaign_validate.add_argument("--campaign-contract", required=True)
    campaign_validate.add_argument("--experiment-card", required=True)

    accept_group = subparsers.add_parser(
        "accept-group",
        help="Record the immutable parent decision for the latest quality gate",
    )
    accept_group.add_argument("--gate-id", required=True)
    accept_group.add_argument("--decision", choices=["accept", "reject"], required=True)
    accept_group.add_argument("--quality", type=int, required=True)
    accept_group.add_argument("--note", default="")

    report = subparsers.add_parser(
        "report", help="Show per-CLI/model run, token, quota, and acceptance evidence"
    )
    report.add_argument("--days", type=int, default=7)
    report.add_argument("--run-id")
    report.add_argument("--limit", type=int, default=100)

    route = subparsers.add_parser(
        "route", help="Rank available agents without invoking one"
    )
    add_task_args(route)
    route.add_argument("--mode", choices=sorted(VALID_MODES), default="advisory")

    run = subparsers.add_parser("run", help="Invoke one bounded worker")
    add_task_args(run)
    run.add_argument("--agent", default="auto")
    run.add_argument(
        "--override-pace-brake", metavar="REASON",
        help="Allow one explicit agent run through an active pace brake; record the reason",
    )
    run.add_argument("--model")
    run.add_argument("--execution-profile")
    run.add_argument("--root-task-id")
    run.add_argument("--attempt-id")
    run.add_argument("--mode", choices=sorted(VALID_MODES), default="advisory")
    run.add_argument(
        "--force-delegation",
        action="store_true",
        help="Allow a validated SKIP assessment to be delegated; hard gates still apply",
    )
    run.add_argument("--workspace", default=str(Path.cwd()))
    run.add_argument("--timeout", type=int, default=900)
    run.add_argument(
        "--office-channel",
        action="append",
        default=[],
        metavar="NAME",
        help="Peek at up to 20 untrusted Office messages from this channel for relay profiles (repeatable).",
    )
    run.add_argument(
        "--office-parent",
        default=None,
        metavar="ADDRESS",
        help="Office address of the parent session, mounted as the MCP peer for shell-less contractors.",
    )
    run.add_argument("--allow-write", action="store_true")
    run.add_argument("--allow-native-subagents", action="store_true")
    run.add_argument("--native-subagent-limit", type=int)
    run_web = run.add_mutually_exclusive_group()
    run_web.add_argument(
        "--enable-web", dest="web_mode", action="store_const", const="enabled"
    )
    run_web.add_argument(
        "--disable-web", dest="web_mode", action="store_const", const="disabled"
    )
    run.add_argument("--inherit-api-keys", action="store_true")
    run.add_argument(
        "--runtime-profile", choices=sorted(RUNTIME_PROFILES), default="standard"
    )
    run.add_argument(
        "--knowledge-mode", choices=sorted(KNOWLEDGE_MODES), default="snapshot"
    )
    run.add_argument("--max-prompt-bytes", type=int)
    run.add_argument("--max-model-tool-calls", type=int)
    run.add_argument(
        "--required-inputs-file",
        help="JSON manifest of relative execution-worktree inputs and SHA-256 hashes",
    )
    run.add_argument("--campaign-contract")
    run.add_argument("--experiment-card")
    run.add_argument("--dry-run", action="store_true")
    run.add_argument("--output-dir")

    council = subparsers.add_parser(
        "council", help="Invoke a dynamic model-level council in parallel"
    )
    add_task_args(council)
    council.add_argument("--agents", default="auto")
    council.add_argument(
        "--count",
        type=int,
        help="Council size; defaults to 2 or every eligible member with --all-models",
    )
    council.add_argument("--all-models", action="store_true")
    council.add_argument("--mode", choices=sorted(VALID_MODES), default="review")
    council.add_argument(
        "--force-delegation",
        action="store_true",
        help="Allow a validated SKIP assessment to run; hard gates still apply",
    )
    council.add_argument("--workspace", default=str(Path.cwd()))
    council.add_argument("--timeout", type=int, default=900)
    council.add_argument("--allow-write", action="store_true")
    council.add_argument("--allow-native-subagents", action="store_true")
    council.add_argument("--native-subagent-limit", type=int)
    council_web = council.add_mutually_exclusive_group()
    council_web.add_argument(
        "--enable-web", dest="web_mode", action="store_const", const="enabled"
    )
    council_web.add_argument(
        "--disable-web", dest="web_mode", action="store_const", const="disabled"
    )
    council.add_argument("--inherit-api-keys", action="store_true")
    council.add_argument(
        "--required-inputs-file",
        help="JSON manifest of relative execution-worktree inputs and SHA-256 hashes",
    )
    council.add_argument("--dry-run", action="store_true")
    council.add_argument("--output-dir")
    return parser


def ensure_workspace(value: str) -> Path:
    path = Path(value).expanduser().resolve()
    if not path.is_dir():
        raise FleetError(f"Workspace is not a directory: {path}")
    return path


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    root: Path | None = None
    try:
        if args.action == "delegation-policy":
            try:
                facts = json.loads(Path(args.scope_file).read_text(encoding="utf-8-sig"))
                result = delegation_policy.decide(facts)
            except (OSError, ValueError) as exc:
                raise FleetError(str(exc)) from exc
            sys.stdout.buffer.write(canonical_json_bytes(result))
            return EXIT_SUCCESS
        if args.action == "lane-policy":
            try:
                request = lane_policy.load_bounded_request_file(
                    Path(args.request_file)
                )
                result = lane_policy.evaluate(request)
            except (OSError, ValueError) as exc:
                raise FleetError(str(exc)) from exc
            sys.stdout.buffer.write(canonical_json_bytes(result))
            return EXIT_SUCCESS
        if args.action == "incident-report":
            root = state_root(args.state_dir)
            result = incident_report(root)
            sys.stdout.buffer.write(canonical_json_bytes(result))
            return EXIT_SUCCESS
        root = state_root(args.state_dir)
        profiles = load_profiles(Path(args.profiles).expanduser().resolve())
        cwd = Path.cwd().resolve()
        if args.action == 'availability-recheck':
            profile = profiles[args.agent]
            pool = str(profile.get('quota_pool_id') or args.agent)
            result = quota_availability.check(
                root, pool, {}, lock_factory=ReleasableKernelLock, force_recheck=True,
                probe=lambda: native_availability.native_probe(sys.modules[__name__], profile, root),
            )
        elif args.action == "doctor":
            result = doctor_profiles(profiles, deep=args.deep, cwd=cwd)
        elif args.action == "status":
            if args.days < 1 or args.days > 365:
                raise FleetError("--days must be between 1 and 365")
            records = read_usage(root, days=args.days)
            quota_snapshots, quota_collection = current_quota_views(root, profiles)
            result = {
                "action": "status",
                "days": args.days,
                "state_dir": str(root),
                "successful_runs": usage_counts(records),
                "run_count": len(records),
                "quota_snapshots": quota_snapshots,
                "quota_collection": quota_collection,
                "usage_summary": fleet_report(
                    root,
                    profiles=profiles,
                    days=args.days,
                    run_id=None,
                    limit=100,
                )["by_agent"],
                "records": records,
                "writes_performed": 0,
            }
        elif args.action == "quota-record":
            if args.agent not in profiles:
                raise FleetError(f"Unknown quota profile: {args.agent}")
            snapshot, path = adaptive.record_quota(
                root,
                agent=args.agent,
                quota_pool_id=adaptive.pool_id_for_profile(args.agent, profiles[args.agent]),
                short_remaining_fraction=(
                    args.short_remaining_pct / 100.0
                    if args.short_remaining_pct is not None
                    else None
                ),
                weekly_remaining_fraction=(
                    args.weekly_remaining_pct / 100.0
                    if args.weekly_remaining_pct is not None
                    else None
                ),
                monthly_remaining_fraction=(
                    args.monthly_remaining_pct / 100.0
                    if args.monthly_remaining_pct is not None
                    else None
                ),
                credits_remaining=args.credits_remaining,
                short_reset_at=args.short_reset_at,
                weekly_reset_at=args.weekly_reset_at,
                monthly_reset_at=args.monthly_reset_at,
                observed_at=args.observed_at,
                source=args.source,
                confidence=args.confidence,
                note=args.note,
                valid_for_hours=args.valid_for_hours,
            )
            result = {
                "action": "quota-record",
                "status": "RECORDED",
                "snapshot": snapshot,
                "record_path": str(path.resolve()),
                "writes_performed": 1,
            }
        elif args.action == "quota-status":
            quota_snapshots, quota_collection = current_quota_views(root, profiles)
            pace_latest = quota_collection.get("pace_latest")
            pace_written = (
                isinstance(pace_latest, dict) and pace_latest.get("written") is True
            )
            result = {
                "action": "quota-status",
                "state_dir": str(root),
                "quota_snapshots": quota_snapshots,
                "quota_collection": quota_collection,
                # Truthful write count: a successful pace/latest.json export
                # is a performed write even though no quota record changed.
                "writes_performed": 1 if pace_written else 0,
            }
        elif args.action == "reparse-usage":
            result = reparse_run_usage(root, run_id=args.run_id)
        elif args.action == "reparse-handoff":
            result = reparse_run_handoff(
                root, run_id=args.run_id, expected_record_sha256=args.expected_record_sha256,
                expected_stdout_sha256=args.expected_stdout_sha256,
            )
        elif args.action == "accept":
            result = evaluate_run(
                root,
                run_id=args.run_id,
                quality_score=args.quality,
                criteria_pass=args.criteria_pass == "yes",
                note=args.note,
                first_pass=optional_bool(args.first_pass),
                tests_pass=optional_bool(args.tests_pass),
                reviewer_accepted=optional_bool(args.reviewer_accepted),
                repair_count=args.repair_count,
                human_review_minutes=args.human_review_minutes,
                delegation_prep_minutes=args.delegation_prep_minutes,
                reopened_7d=optional_bool(args.reopened_7d),
                instruction_compliance=args.instruction_compliance,
                scope_control=args.scope_control,
                code_quality=args.code_quality,
                visual_quality=args.visual_quality,
                regressions_found=args.regressions_found,
                failure_class=args.failure_class,
            )
        elif args.action == "outcome":
            result = append_run_outcome(
                root,
                run_id=args.run_id,
                reopened_7d=optional_bool(args.reopened_7d),
                regressions_found=args.regressions_found,
                note=args.note,
            )
        elif args.action in {"quality-gate", "security-gate"}:
            if args.timeout < 30 or args.timeout > 7200:
                raise FleetError("--timeout must be between 30 and 7200 seconds")
            result = run_quality_gate(
                root,
                profiles=profiles,
                contract_path=Path(args.contract).expanduser().resolve(),
                run_ids=list(args.run_id),
                previous_gate_id=args.previous_gate_id,
                auditor=args.auditor,
                auditor_model=args.auditor_model,
                complexity=args.complexity,
                workspace=(
                    Path(os.path.abspath(Path(args.workspace).expanduser()))
                    if args.supplemental_evidence else ensure_workspace(args.workspace)
                ),
                timeout=args.timeout,
                dry_run=args.dry_run,
                output_root=parse_output_root(args.output_dir),
                gate_kind="security" if args.action == "security-gate" else "quality",
                complementary_review=getattr(args, "complementary_review", False),
                assessment_file=args.assessment_file,
                supplemental_manifest=(
                    Path(args.supplemental_evidence) if args.supplemental_evidence else None
                ),
                public_source_manifest=(
                    Path(args.public_source_manifest).expanduser().resolve()
                    if getattr(args, "public_source_manifest", None)
                    else None
                ),
            )
        elif args.action == "quality-repair":
            if args.timeout < 30 or args.timeout > 7200:
                raise FleetError("--timeout must be between 30 and 7200 seconds")
            result = dispatch_quality_repairs(
                root,
                profiles=profiles,
                gate_id=args.gate_id,
                timeout=args.timeout,
                dry_run=args.dry_run,
                output_root=parse_output_root(args.output_dir),
                max_model_tool_calls=args.max_model_tool_calls,
            )
        elif args.action == "quality-status":
            result = quality_gate_status(root, gate_id=args.gate_id)
        elif args.action == "campaign-validate":
            context = load_scientific_campaign_context(
                Path(args.campaign_contract).expanduser().resolve(),
                Path(args.experiment_card).expanduser().resolve(),
            )
            result = {
                "action": "campaign-validate",
                "status": "VALID",
                "scientific_campaign": context,
                "writes_performed": 0,
            }
        elif args.action == "accept-group":
            result = accept_quality_group(
                root,
                profiles=profiles,
                gate_id=args.gate_id,
                decision=args.decision,
                quality_score=args.quality,
                note=args.note,
            )
        elif args.action == "report":
            if args.days < 1 or args.days > 365:
                raise FleetError("--days must be between 1 and 365")
            if args.limit < 1 or args.limit > 1000:
                raise FleetError("--limit must be between 1 and 1000")
            result = fleet_report(
                root,
                profiles=profiles,
                days=args.days,
                run_id=args.run_id,
                limit=args.limit,
            )
        elif args.action == "route":
            task = read_task(args.task, args.task_file)
            result = route_task(
                task,
                profiles=profiles,
                kind=args.kind,
                complexity=args.complexity,
                root=root,
                cwd=cwd,
                assessment_file=args.assessment_file,
                mode=args.mode,
                allow_synthetic_worker=args.mode == "implement",
            )
        elif args.action == "run":
            if args.timeout < 30 or args.timeout > 7200:
                raise FleetError("--timeout must be between 30 and 7200 seconds")
            if args.override_pace_brake is not None and args.agent == "auto":
                raise FleetError("--override-pace-brake requires an explicit --agent")
            task = read_task(args.task, args.task_file)
            workspace = ensure_workspace(args.workspace)
            if args.agent in profiles and is_beam_profile(
                profiles.get(args.agent)
            ):
                # Check the resolved path before route/readiness probes can
                # start any provider process or load its DPAPI credential.
                workspace = qualify_beam_workspace(
                    args.agent, profiles[args.agent], workspace
                )
            if bool(args.campaign_contract) != bool(args.experiment_card):
                raise FleetError(
                    "Scientific campaign run requires both --campaign-contract and --experiment-card"
                )
            scientific_campaign = (
                load_scientific_campaign_context(
                    Path(args.campaign_contract).expanduser().resolve(),
                    Path(args.experiment_card).expanduser().resolve(),
                )
                if args.campaign_contract
                else None
            )
            agent_id, selected_kind, route = choose_agent(
                args.agent,
                task,
                profiles=profiles,
                kind=args.kind,
                complexity=args.complexity,
                root=root,
                cwd=workspace,
                assessment_file=args.assessment_file,
                mode=args.mode,
                force_delegation=args.force_delegation,
                override_pace_brake=args.override_pace_brake is not None,
            )
            if route["delegation_decision"] == "SKIP" and not args.force_delegation:
                sys.stdout.buffer.write(canonical_json_bytes({**route, "action": "run"}))
                return EXIT_SUCCESS
            if args.mode not in profiles[agent_id]["supported_modes"]:
                if args.agent != "auto":
                    raise FleetError(
                        f"{profiles[agent_id]['display_name']} does not support safe "
                        f"{args.mode} mode in Agent Fleet"
                    )
                fallback = next(
                    (
                        row
                        for row in route["rankings"]
                        if row["eligible"]
                        and args.mode in profiles[str(row["agent"])]["supported_modes"]
                    ),
                    None,
                )
                if fallback is None:
                    raise FleetError(
                        f"No eligible agent supports safe {args.mode} mode"
                    )
                skipped_agent = agent_id
                agent_id = str(fallback["agent"])
                route["selected_agent"] = agent_id
                route["selected_model"] = str(fallback["suggested_model"])
                route["selection_note"] = (
                    f"Skipped {skipped_agent}: safe {args.mode} mode is unsupported"
                )
            if args.model:
                route["selected_model"] = validate_configured_model(
                    agent_id, profiles[agent_id], args.model
                )
                prior_note = route.get("selection_note")
                route["selection_note"] = (
                    f"{prior_note}; explicit model override"
                    if prior_note
                    else "Explicit model override"
                )
            previous_execution_profile_id = route.get("selected_execution_profile_id")
            if args.execution_profile:
                owner = execution_profile_owner(profiles, args.execution_profile)
                if owner is not None and args.execution_profile not in profiles[
                    agent_id
                ].get("execution_profiles", {}):
                    raise FleetError(
                        f"Execution profile {args.execution_profile} requires "
                        f"--agent {owner}"
                    )
            try:
                selected_execution = resolve_execution_profile(
                    agent_id,
                    profiles[agent_id],
                    complexity=args.complexity,
                    mode=args.mode,
                    required_tools=route["task_profile"].get("required_tools", []),
                    model_override=(
                        str(route["selected_model"]) if args.model else None
                    ),
                    execution_profile_override=args.execution_profile,
                )
            except routing_v2.RoutingV2Error as exc:
                raise FleetError(str(exc)) from exc
            override_gates = routing_v2.hard_gates(
                selected_execution,
                profile=profiles[agent_id],
                assessment=route["task_profile"],
                readiness=route["readiness"][agent_id],
                quota=route["quota_snapshots"][agent_id],
                mode=args.mode,
                override_pace_brake=args.override_pace_brake is not None,
            )
            if is_beam_profile(profiles[agent_id]) and args.agent != "auto":
                override_gates = [
                    gate
                    for gate in override_gates
                    if str(gate.get("code"))
                    not in {"routing-enabled", "runtime-readiness"}
                ]
            failed_override_gates = [
                str(gate["code"]) for gate in override_gates if not bool(gate["passed"])
            ]
            explicit_canary = (
                args.agent != "auto"
                and routing_v2.permits_explicit_canary(
                    selected_execution, override_gates
                )
            )
            if failed_override_gates and not explicit_canary:
                raise FleetError(
                    "Selected execution profile fails hard gates: "
                    + ", ".join(failed_override_gates)
                )
            route["selected_execution_profile"] = selected_execution
            route["selected_execution_profile_id"] = selected_execution[
                "execution_profile_id"
            ]
            route["selected_model"] = selected_execution["model"]
            route["gate_results"] = override_gates
            route["explicit_canary_override"] = explicit_canary
            if (
                selected_execution["execution_profile_id"]
                != previous_execution_profile_id
            ):
                route["selection_changed_from_baseline"] = True
                prior_note = route.get("selection_note")
                execution_note = "Explicit execution profile override: " + str(
                    selected_execution["execution_profile_id"]
                )
                route["selection_note"] = (
                    f"{prior_note}; {execution_note}" if prior_note else execution_note
                )
            native_subagent_policy = resolve_native_subagent_policy(
                complexity=args.complexity,
                explicit_limit=args.native_subagent_limit,
                legacy_allow=args.allow_native_subagents,
                agent_id=agent_id,
            )
            native_subagent_limit = int(native_subagent_policy["limit"])
            route["native_subagent_policy"] = native_subagent_policy
            enable_web = resolve_web_access(kind=selected_kind, web_mode=args.web_mode)
            route["web_access"] = "enabled" if enable_web else "disabled"
            campaign_run_id = (
                f"run-{dt.datetime.now(dt.timezone.utc).strftime('%Y%m%dT%H%M%SZ')}-"
                f"{uuid.uuid4().hex[:10]}"
                if scientific_campaign is not None
                else None
            )
            if scientific_campaign is not None:
                assert campaign_run_id is not None
                reserve_scientific_campaign_run(
                    root,
                    scientific_campaign,
                    run_id=campaign_run_id,
                    timeout=args.timeout,
                    dry_run=args.dry_run,
                )
            try:
                result = execute_single(
                    task,
                    profiles=profiles,
                    agent_id=agent_id,
                    mode=args.mode,
                    kind=selected_kind,
                    complexity=args.complexity,
                    model_override=args.model,
                    execution_profile=selected_execution,
                    root_task_id=validate_trace_id(
                        args.root_task_id,
                        pattern=ROOT_TASK_ID_PATTERN,
                        label="--root-task-id",
                    ),
                    attempt_id=validate_trace_id(
                        args.attempt_id,
                        pattern=ATTEMPT_ID_PATTERN,
                        label="--attempt-id",
                    ),
                    task_profile=route["task_profile"],
                    route_event=route_telemetry(route, agent_id=agent_id),
                    workspace=workspace,
                    timeout=args.timeout,
                    allow_write=args.allow_write,
                    native_subagent_limit=native_subagent_limit,
                    enable_web=enable_web,
                    inherit_api_keys=args.inherit_api_keys,
                    dry_run=args.dry_run,
                    output_root=parse_output_root(args.output_dir),
                    root=root,
                    native_subagent_policy=native_subagent_policy,
                    runtime_profile=args.runtime_profile,
                    knowledge_mode=args.knowledge_mode,
                    max_prompt_bytes=args.max_prompt_bytes,
                    max_model_tool_calls=args.max_model_tool_calls,
                    required_inputs_file=args.required_inputs_file,
                    run_id_override=campaign_run_id,
                    scientific_campaign=scientific_campaign,
                    office_channels=args.office_channel,
                    office_parent=args.office_parent,
                    pace_brake_override=args.override_pace_brake,
                )
            except Exception:
                if scientific_campaign is not None and not args.dry_run:
                    assert campaign_run_id is not None
                    finish_scientific_campaign_run(
                        root,
                        scientific_campaign,
                        run_id=campaign_run_id,
                        run_status="FAILED",
                    )
                raise
            if scientific_campaign is not None and not args.dry_run:
                assert campaign_run_id is not None
                finish_scientific_campaign_run(
                    root,
                    scientific_campaign,
                    run_id=campaign_run_id,
                    run_status=str(result.get("status", "FAILED")),
                )
            result["route"] = route
            result = finalize_run_watch_event(result)
        elif args.action == "council":
            if args.timeout < 30 or args.timeout > 7200:
                raise FleetError("--timeout must be between 30 and 7200 seconds")
            if args.mode == "implement" and not args.allow_write:
                raise FleetError("Implement council requires --allow-write")
            if args.mode != "implement" and args.allow_write:
                raise FleetError("--allow-write is valid only for implement council")
            task = read_task(args.task, args.task_file)
            workspace = ensure_workspace(args.workspace)
            route = route_task(
                task,
                profiles=profiles,
                kind=args.kind,
                complexity=args.complexity,
                root=root,
                cwd=workspace,
                allow_no_eligible=args.agents != "auto",
                assessment_file=args.assessment_file,
                mode=args.mode,
                force_delegation=args.force_delegation,
            )
            if route["delegation_decision"] == "SKIP" and not args.force_delegation:
                sys.stdout.buffer.write(canonical_json_bytes({**route, "action": "council"}))
                return EXIT_SUCCESS
            selected_kind = str(route["selected_kind"])
            enable_web = resolve_web_access(kind=selected_kind, web_mode=args.web_mode)
            route["web_access"] = "enabled" if enable_web else "disabled"
            selected_members = select_council_members(
                route,
                profiles,
                mode=args.mode,
                requested=args.agents,
                count=args.count,
                all_models=args.all_models,
            )
            for member in selected_members:
                member_agent = str(member["agent"])
                try:
                    member_execution = resolve_execution_profile(
                        member_agent,
                        profiles[member_agent],
                        complexity=args.complexity,
                        mode=args.mode,
                        required_tools=route["task_profile"].get("required_tools", []),
                        model_override=str(member["model"]),
                    )
                except routing_v2.RoutingV2Error as exc:
                    raise FleetError(str(exc)) from exc
                member_gates = routing_v2.hard_gates(
                    member_execution,
                    profile=profiles[member_agent],
                    assessment=route["task_profile"],
                    readiness=route["readiness"][member_agent],
                    quota=route["quota_snapshots"][member_agent],
                    mode=args.mode,
                )
                failed_member_gates = [
                    str(gate["code"])
                    for gate in member_gates
                    if not bool(gate["passed"])
                ]
                if failed_member_gates:
                    raise FleetError(
                        f"Council member {member['id']} fails hard gates: "
                        + ", ".join(failed_member_gates)
                    )
                member["execution_profile"] = member_execution
                member["gate_results"] = member_gates
                member["native_subagent_policy"] = resolve_native_subagent_policy(
                    complexity=args.complexity,
                    explicit_limit=args.native_subagent_limit,
                    legacy_allow=args.allow_native_subagents,
                    agent_id=member_agent,
                )
            route["native_subagent_policies"] = {
                str(member["id"]): member["native_subagent_policy"]
                for member in selected_members
            }
            council_root_task_id = f"task-{uuid.uuid4().hex}"
            with concurrent.futures.ThreadPoolExecutor(
                max_workers=len(selected_members)
            ) as executor:
                futures = {
                    str(member["id"]): executor.submit(
                        execute_single,
                        task,
                        profiles=profiles,
                        agent_id=str(member["agent"]),
                        mode=args.mode,
                        kind=selected_kind,
                        complexity=args.complexity,
                        model_override=str(member["model"]),
                        execution_profile=member["execution_profile"],
                        root_task_id=council_root_task_id,
                        attempt_id=f"attempt-{uuid.uuid4().hex}",
                        task_profile=route["task_profile"],
                        route_event=route_telemetry(
                            route, agent_id=str(member["agent"])
                        ),
                        workspace=workspace,
                        timeout=args.timeout,
                        allow_write=args.allow_write,
                        native_subagent_limit=int(
                            member["native_subagent_policy"]["limit"]
                        ),
                        enable_web=enable_web,
                        inherit_api_keys=args.inherit_api_keys,
                        dry_run=args.dry_run,
                        output_root=parse_output_root(args.output_dir),
                        root=root,
                        native_subagent_policy=member["native_subagent_policy"],
                        required_inputs_file=args.required_inputs_file,
                    )
                    for member in selected_members
                }
                results: list[dict[str, Any]] = []
                for member in selected_members:
                    member_id = str(member["id"])
                    try:
                        results.append(futures[member_id].result())
                    except (
                        Exception
                    ) as exc:  # Keep independent worker failures visible.
                        results.append(
                            {
                                "action": "run",
                                "status": "FAILED",
                                "member": member_id,
                                "agent": member["agent"],
                                "model": member["model"],
                                "error": f"{type(exc).__name__}: {exc}",
                            }
                        )
            result = {
                "action": "council",
                "status": completed_council_status(results, dry_run=args.dry_run),
                "selected_agents": [member["agent"] for member in selected_members],
                "selected_members": selected_members,
                "route": route,
                "results": results,
                "parallel_isolated_worktrees": args.mode == "implement",
                "synthesis_required": True,
            }
        else:
            raise FleetError(f"Unsupported action: {args.action}")
        sys.stdout.buffer.write(canonical_json_bytes(result))
        return result_exit_code(result)
    except (FleetError, adaptive.AdaptiveError) as exc:
        incident_logging = None
        if root is not None:
            incident_logging = record_incident_event(
                root, refused_incident_event(getattr(args, "action", None), exc)
            )
        error = {
            "action": getattr(args, "action", None),
            "status": "REFUSED",
            "error": str(exc),
            "incident_logging": incident_logging,
            "writes_performed": 0,
        }
        sys.stderr.buffer.write(canonical_json_bytes(error))
        return EXIT_REFUSED


if __name__ == "__main__":
    raise SystemExit(main())
